INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(4971, 'plPL', 'Kwestia czasu', 'Ktoś majstrował przy linii czasu w Andorhalu – jakaś złowroga siła, najpewniej Plaga! Mogę spróbować utrzymać tu nienaruszony bieg czasu i naprawić to, co zostało uszkodzone, ale potrzebuję twojej pomocy, by nikt mi w tym nie przeszkadzał.$B$BPasożyty czasu – padlinożercy żywiący się nićmi zmienionego biegu czasu – zalęgły się w silosach Andorhalu. Jedyny widoczny ślad ich obecności to błękitny puls zniekształcenia. Spowalniają moje wróżby; proszę, $N, pomóż mi i użyj tego czasowego przemieszczacza, by wypłoszyć te pasożyty.', 'Użyj czasowego przemieszczacza w pobliżu jednego z silosów Andorhalu, by odsłonić pasożyty czasu.$B$BZabij 10 pasożytów czasu, a potem zwróć czasowy przemieszczacz Chromie w karczmie w Andorhalu na Zachodnich Plagowiskach.', '', 'Wróć do Chromie w Ruinach Andorhalu na Zachodnich Plagowiskach.', '', '', '', '', 0),
(4972, 'plPL', 'Odliczanie czasu', 'Potrzebuję, żebyś $gsięgnął:sięgnęła; do świata poza tym pokojem, $N. Pozwól, że wyjaśnię.$B$BWidzisz, jak ten pokój różni się od reszty Andorhalu. Moje stado działa na wiele sposobów i w wielu różnych liniach czasu. Aby naprawić szkody w Andorhalu, działam teraz z innej linii czasu, żeby zbytnio jej nie skazić. Aby jednak kontynuować, potrzebuję czasowych drobiazgów – takich, które utknęły w chwili, gdy uderzyła zaraza. Znajdziesz je w kasetkach w zrujnowanych budynkach tego niegdyś dumnego miasta.', 'Odnajdź 5 zegarków z Andorhalu, ukrytych w kasetkach wśród gruzów miasta. Wróć z nimi do Chromie w karczmie w Andorhalu na Zachodnich Plagowiskach.', '', 'Wróć do Chromie w Ruinach Andorhalu na Zachodnich Plagowiskach.', '', '', '', '', 0),
(4973, 'plPL', 'Odliczanie czasu', 'Jeśli zechcesz pomóc jeszcze raz, twoja pomoc na pewno mi się przyda. Chętnie przyjmę kolejne zegarki, które odnajdziesz w ruinach Andorhalu. Z pewnością pomagają mi utrzymać równowagę wobec złowrogiej siły, która majstruje tu przy linii czasu.$B$BW zamian za te zegarki dam ci kolejny przedmiot, który – jak podejrzewam – w przyszłości bardzo ci się przyda.', 'Odnajdź 5 zegarków z Andorhalu wśród gruzów miasta i wróć z nimi do Chromie w karczmie w Andorhalu na Zachodnich Plagowiskach.', '', 'Wróć do Chromie w Ruinach Andorhalu na Zachodnich Plagowiskach.', '', '', '', '', 0),
(4984, 'plPL', 'Cierpią także zwierzęta', 'Choć sam niewiele mogłem zrobić, by pokrzyżować plany Plagi, przybyłem na te ziemie, by próbować leczyć szkody wyrządzone naturze. Zwierzęta cierpią od zarazy, która wciąż dusi te ziemie, i nie mogą znaleźć litości ani spokoju. Proszę cię, byś $gdokończył:dokończyła; to, czego ja tu nie zdołałem.$B$BDla cierpiących zwierząt nie ma innego ocalenia niż słodkie i miłosierne wyzwolenie. Odszukaj chore wilki w okolicy i skróć ich męki. Proszę, $N, zakończ ich cierpienie – to z pewnością ukoi i moje.', 'Zabij 8 chorych wilków, a potem wróć do Mulgrisa Głębokiej Rzeki w Wijącym się Nawiedzisku na Zachodnich Plagowiskach.$B$B', '', 'Wróć do Mulgrisa Głębokiej Rzeki nad Jeziorem Darrowmere na Zachodnich Plagowiskach.', '', '', '', '', 0),
(4985, 'plPL', 'Cierpią także zwierzęta', 'Na wschód stąd, niedaleko miejsca, gdzie zaczynają się Wschodnie Plagowiska, przemierzały niegdyś okolicę dumne i majestatyczne grizli. Zaraza wypuszczona przez Plagę zniszczyła i te zwierzęta. Błąkają się po okolicy, udręczone sztywnieniem mięśni i gniciem futra i ciała.$B$BProszę cię, byś i im $gskrócił:skróciła; męki. Jedynym lekarstwem na ich cierpienie jest szybka śmierć – taka, którą musi zadać twoja ręka.', 'Zabij 8 chorych grizli, a potem wróć do Mulgrisa Głębokiej Rzeki w Wijącym się Nawiedzisku na Zachodnich Plagowiskach.', '', 'Wróć do Mulgrisa Głębokiej Rzeki nad Jeziorem Darrowmere na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5051, 'plPL', 'Dwie połówki w jedną całość', 'Biedny duch wciąż bełkocze:$B$B„Tak mi zimno, John. Przynieś mi swój amulet, a będziemy razem! Szybko, John, zanim zaraza zmieni nas w ohydne bestie! Nie widzę cię, John... ale wiem, że jesteś blisko. Czuję cię przy sobie”.$B$BMoże gdyby odnaleźć drugą połówkę amuletu i złożyć go w całość, byłoby to właśnie to, czego szuka duch Janice Felstone.', 'Odszukaj drugą połówkę amuletu szczęścia gdzieś na farmie Felstone\'ów na Zachodnich Plagowiskach i złóż go w całość.$B$BDaj amulet szczęścia Janice Felstone na farmie Felstone\'ów na Zachodnich Plagowiskach.', '', 'Wróć do Janice Felstone na Zagonie Felstone\'ów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5058, 'plPL', 'Dziennik pani Dalson', '', '', '', '', '', '', '', '', 0),
(5059, 'plPL', 'Pod kluczem', '', '', '', '', '', '', '', '', 0),
(5060, 'plPL', 'Pod kluczem', '', '', '', 'Wróć do zamkniętej szafki na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5092, 'plPL', 'Utoruj drogę', 'Zachodnia i północna droga do Andorhalu są dobrze umocnione, dlatego zamierzam uderzyć na miasto od słabiej bronionej drogi wschodniej. Pierwszą linią obrony Plagi jest bufor nieumarłych, którzy opanowali Wzgórze Smutku. Jeśli mamy ruszyć na Andorhal, musimy przejść przez Wzgórze Smutku.$B$BTwoim pierwszym zadaniem będzie utorowanie drogi przez Wzgórze Smutku. Przetrzeb szkielety i ghule, które nawiedzają okolicę; gdy skończysz, zamelduj się u mnie!', 'Zabij 10 szkieletowych obdzieraczy i 10 śliniących się ghuli na Wzgórzu Smutku.$B$BWróć do dowódcy Ashlama Mężnopięścia w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', 'Wróć do dowódcy Ashlama Mężnopięścia w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5142, 'plPL', 'Mała Pamela', 'Tak wielu z nas zginęło w bitwie o Włości Darrow. Tak wielu zginęło... albo spotkało ich coś gorszego.$B$BGdy zaczęła się bitwa, ukryłam moją bratanicę Pamelę i nie wiem, co się z nią stało. Jestem tylko błąkającym się duchem, ale moje serce wciąż pragnie poznać los Pameli.$B$BProszę cię, $N. Czy udasz się do Włości Darrow i jej poszukasz? To na wschodzie, za Plonami Gahrrona.', 'Odnajdź Pamelę Redpath we Włościach Darrow.', '', '', '', '', '', '', 0),
(5152, 'plPL', 'Ciocia Marlene', 'Och, jestem taka samotna! Gdzie jest moja rodzina? Ciocia Marlene kazała mi tu zostać, ale potem odeszła i już nie wróciła! A mój tata... $gwidziałeś:widziałaś; go?$B$BMoże ciocia Marlene wie, gdzie on jest. Mieszka niedaleko Andorhalu, w domu na południe od niego. Chyba na wzgórzu... mówiła, że na wzgórzu.$B$BProszę, $N. Jesteś $gmoim nowym przyjacielem:moją nową przyjaciółką;! Porozmawiasz za mnie z ciocią?', 'Porozmawiaj z Marlene na południe od Ruin Andorhalu.', '', '', '', '', '', '', 0),
(5153, 'plPL', 'Dziwna historyczka', 'Chciałabym, żeby Joseph znów mógł być ze swoją córką, ale to niemożliwe. Plaga wypaczyła jego duszę i stał się potworem. Och, jest zgubiony!$B$BAle może zdołamy zmienić jego los.$B$BPoszukaj na cmentarzu przed domem pomnika Josepha. Jego ciała tam nie ma, bo lata temu zostało stratowane i zniszczone, ale pod pomnikiem leży jego obrączka ślubna. Zanieś ją Chromie... dziwnej gnomce o bardzo dziwnych mocach.$B$BChronia mieszka w zrujnowanej karczmie w północno-zachodnim rogu Andorhalu.', 'Zanieś obrączkę ślubną Josepha Chromie.', '', 'Wróć do Chromie w Ruinach Andorhalu na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5154, 'plPL', 'Kroniki Włości Darrow', 'Aby ocalić Josepha Redpatha, musimy najpierw poznać jego przeszłość. Dowiemy się jej z Kronik Włości Darrow, księgi przechowywanej w ratuszu Andorhalu.$B$BPrzynieś mi tę księgę. Wtedy poznamy los Josepha, a przy odrobinie szczęścia... zmienimy go!', 'Przynieś Kroniki Włości Darrow Chromie w Andorhalu.', '', 'Wróć do Chromie w Ruinach Andorhalu na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5161, 'plPL', 'Gniew Błękitnego Stada', 'Rozumiemy, co próbuje osiągnąć przeklęty pomiot Śmiercioskrzydłego, i wiemy, że nie można na to pozwolić.$B$BPonieważ Czarna Góra zapewnia Nefarianowi ochronę, coraz trudniej nam interweniować.$B$BMożemy jednak dodać ci mocy, $gśmiertelniku:śmiertelniczko; – jeśli tak postanowisz.$B$BDroga, która przed tobą leży, pełna jest niebezpieczeństw. Musisz zdecydować, czy przyjmiesz naszą pomoc. Przemyśl to i porozmawiaj ze mną znowu, gdy podejmiesz decyzję.', 'Jeśli chcesz kontynuować, porozmawiaj z Haleh.', '', '', '', '', '', '', 0),
(5162, 'plPL', 'Gniew Błękitnego Stada', 'To tajemną magią władam i to ona pośle cię do twojego następnego celu.$B$BGdy będziesz $ggotów:gotowa;, podróż się rozpocznie. Udasz się na Plagowiska i porozmawiasz z Jezibą.$B$BTo śmiertelnik mądry jak pradawni i cierpliwy jak nieporuszona ziemia. Znajdziesz go w Andorhalu.$B', 'Porozmawiaj z Jezibą na Plagowiskach. Przebywa w Andorhalu.', '', '', '', '', '', '', 0),
(5164, 'plPL', 'Katalog zbłąkanych', 'Haleh nie mogła wybrać lepszego narzędzia sprawiedliwości. Przeczytaj fragment katalogu zbłąkanych i doznaj oświecenia.$B$BJeśli wytrwasz... jeśli zrobisz, o co cię poproszą... jeśli przeżyjesz... będzie z ciebie bohater.', 'Przeczytaj fragment Katalogu zbłąkanych.$B', '', '', '', '', '', '', 0),
(5166, 'plPL', 'Napierśnik Chromatycznego Stada', 'Wykucie potężnego napierśnika, który chroni przed nieustępliwymi atakami Chromatycznego Stada, opiera się na ironii.$B$BŁuski tych samych bestii, z którymi walczymy, trzeba przyszyć do nieskazitelnego karapaksu dojrzałego chromatycznego smoka lub smoczycy. Obecnie nie wiadomo o istnieniu żadnego i należy mieć nadzieję, że żaden nigdy nie powstanie.$B$BWreszcie składnik chyba najtrudniejszy do zdobycia: krew bohaterów.$B$BOstatecznie dzieło to musi wykuć Rzeźbiarz.', 'Aby wykuć Napierśnik Chromatycznego Stada, musisz przynieść Jezibie „Rzeźbiarzowi” następujące przedmioty:$B$B1 chromatyczny karapaks.$B$B10 błyszczących chromatycznych łusek.$B$B10 porcji krwi bohaterów.$B$B10 postrzępionych szwów plugastwa.', '', 'Wróć do Jeziby w Ruinach Andorhalu na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5167, 'plPL', 'Nogawice płytowe chromatycznego buntownika', 'Podstawą nogawic musi być karapaks dojrzałego chromatycznego smoka. Następnie na drucianą ramę nakłada się warstwami błyszczące chromatyczne łuski i zaklina je we krwi bohaterów. Na koniec od wewnątrz nakłada się giętką skórę cienia.', 'Aby wykuć Nogawice płytowe chromatycznego buntownika, musisz przynieść Jezibie „Rzeźbiarzowi” następujące przedmioty:$B$B1 chromatyczny karapaks.$B$B10 błyszczących chromatycznych łusek.$B$B10 porcji krwi bohaterów.$B$B5 skór cienia.', '', 'Wróć do Jeziby w Ruinach Andorhalu na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5210, 'plPL', 'Brat Carlin', 'Dzięki mojej magii Kroniki Włości Darrow zyskały nowe strony na końcu i ich historia sięga teraz poza bitwę. Jeden z dodatkowych fragmentów opowiada o innym członku rodu Redpathów, Carlinie, który przeżył zdradę Josepha. Carlin jest teraz na Plagowiskach na wschodzie, w Kaplicy Świetlistej Nadziei.$B$BWeź księgę i porozmawiaj z nim.', 'Przynieś Rozszerzone kroniki Włości Darrow Carlinowi Redpathowi na Wschodnie Plagowiska.', '', '', '', '', '', '', 0),
(5217, 'plPL', 'Powrót do Obozu Zimnych Wichrów', 'Napełniasz butelkę trującą miksturą z kotła – wystarczy na próbkę do badań.$B$BZ trucizną w ręku pora wrócić do arcykapłanki MacDonnell w Obozie Zimnych Wichrów, by zakończyć misję.', 'Zanieś pełną butelkę z Zagonu Felstone\'ów arcykapłance MacDonnell do Obozu Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5218, 'plPL', 'Kocioł na Zagonie Felstone\'ów', '', '', '', 'Wróć do kotła Plagi na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5220, 'plPL', 'Powrót do Obozu Zimnych Wichrów', 'Ostrożnie napełniasz butelkę posoką z kotła, aż próbka wydaje ci się dość duża.$B$BZ trucizną w ręku pora wrócić do arcykapłanki MacDonnell w Obozie Zimnych Wichrów, by zakończyć misję.', 'Zanieś pełną butelkę z Łez Dalsona arcykapłance MacDonnell do Obozu Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5221, 'plPL', 'Kocioł w Łzach Dalsona', '', '', '', 'Wróć do kotła Plagi na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5223, 'plPL', 'Powrót do Obozu Zimnych Wichrów', 'Ostrożnie napełniasz pustą butelkę; próbka plugawej substancji, która kłębi się pod platformą kotła, chlupocze teraz w kruchym szklanym naczyniu.$B$BZ trucizną w ręku pora wrócić do arcykapłanki MacDonnell w Obozie Zimnych Wichrów, by zakończyć misję.', 'Zanieś pełną butelkę z Wijącego się Nawiedziska arcykapłance MacDonnell do Obozu Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5224, 'plPL', 'Kocioł w Wijącym się Nawiedzisku', '', '', '', 'Wróć do kotła Plagi w Górach Alterak.', '', '', '', '', 0),
(5226, 'plPL', 'Powrót do Obozu Zimnych Wichrów', 'Ostrożnie zakręcasz kurek w panelu, patrząc, jak cuchnąca posoka z kotła skapuje do pustej butelki.$B$BZ trucizną w ręku pora wrócić do arcykapłanki MacDonnell w Obozie Zimnych Wichrów, by zakończyć misję.', 'Zanieś pełną butelkę z Plonów Gahrrona arcykapłance MacDonnell do Obozu Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', '', '', 0),
(5227, 'plPL', 'Kocioł na Plonach Gahrrona', '', '', '', 'Wróć do kotła Plagi na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5382, 'plPL', 'Doktor Theolen Krastinov, Rzeźnik', 'Krastinov odpowiada za śmierć tysięcy. Musi zostać ukarany, musi spotkać go sprawiedliwość.$B$BZnajdź go i zadaj mu męki, jakie zadał niezliczonym niewinnym. Gdy go zniszczysz, spal nasze szczątki. Obróć je w popiół, $N.', 'Odnajdź doktora Theolena Krastinova w Scholomancjum. Zniszcz go, a potem spal Szczątki Evy Sarkhoff i Szczątki Luciena Sarkhoffa. Gdy wykonasz zadanie, wróć do Evy Sarkhoff.$B', '', 'Wróć do Evy Sarkhoff nad Jeziorem Darrowmere na Zachodnich Plagowiskach.', '', 'Spalone szczątki Evy Sarkhoff', 'Spalone szczątki Luciena Sarkhoffa', '', 0),
(5384, 'plPL', 'Kirtonos Herold', 'To jest to, $N.$B$B<Eva wskazuje fiolkę w torbie.>$B$BKrew niewinnych. Najczystsza krew, którą ułagadzano pana Krastinova.$B$BTą krwią można przywołać Kirtonosa. I tą samą krwią Kirtonos musi zostać zniszczony.$B$BZanieś krew na ganek. Umieść ją w koszu żarowym. Kirtonos przybędzie – nie zdoła się oprzeć. Gdy się pojawi, rozpętaj na nim furię i gniew tysiąca niewinnych ofiar.$B$BJeśli ci się uda, zyskasz coś więcej niż tylko naszą wdzięczność.', 'Wróć do Scholomancjum z krwią niewinnych. Odnajdź ganek i umieść krew niewinnych w koszu żarowym. Kirtonos przybędzie, by pożreć twoją duszę.$B$BWalcz dzielnie, nie ustępuj ani na krok! Zniszcz Kirtonosa i wróć do Evy Sarkhoff.$B', '', 'Wróć do Evy Sarkhoff nad Jeziorem Darrowmere na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5461, 'plPL', 'Człowiek, Rez Szept Mrozu', 'Nieumarli boją się życia tak, jak żywi boją się śmierci. Nierzadko istota nieumarła, która zachowała świadomość, po przemianie doszczętnie niszczy wszelkie pozostałości swojego dawnego życia.$B$BNiestety, aby stworzyć artefakt zdolny przywrócić Reza Szepta Mrozu do śmiertelności, potrzebujemy pamiątki z lat, gdy żył wśród żywych.$B$BMusisz udać się do zrujnowanego miasta Stromgard, rodzinnego miasta Szepta Mrozu, i poszukać takiego przedmiotu. Niech ci sprzyja szczęście, $N.', 'Udaj się na Wyżyny Aratorskie, do ruin Stromgardu. Poszukaj w Stromgardzie pamiątki wspomnień. Jeśli znajdziesz taki przedmiot, wróć z nim do sędziego Marduke\'a.', '', 'Wróć do sędziego Marduke\'a nad Jeziorem Darrowmere na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5462, 'plPL', 'Umierający, Rez Szept Mrozu', 'Pamiątkę trzeba zestroić na skażonej ziemi.$B$BPodobno to w Stratholmie Szept Mrozu uległ Królowi Liszowi. Na tej zbroczonej krwią ziemi oddał życie – dobrowolnie i z rozmysłem – by stać się jednym z nieumierających.$B$BTo właśnie tę ziemię trzeba odnaleźć.$B$BJest ktoś taki – nieumarły odszczepieniec od Plagi, uwolniony przez Królową Banshee, lecz wierny sprawie Argentowego Brzasku. Odnajdź go: Leonida Barthalomew Czcigodnego. Może wie więcej. Udaj się do Świetlistej Nadziei, $N. ', 'Udaj się do Świetlistej Nadziei na Wschodnich Plagowiskach i odszukaj Leonida Barthalomew Czcigodnego. Pokaż mu pamiątkę wspomnień i opowiedz o wszystkim, czego się $gdowiedziałeś:dowiedziałaś;.', '', '', '', '', '', '', 0),
(5465, 'plPL', 'Pamiątka związana z duszą', 'Wróć z pamiątką do Marduke\'a, $N. Pouczy cię, jak jej użyć.', 'Wróć do sędziego Marduke\'a w Caer Darrow. Pokaż mu pamiątkę związaną z duszą.', '', '', '', '', '', '', 0),
(5466, 'plPL', 'Lisz, Rez Szept Mrozu', 'Zostało tylko jedno zadanie, $N. Zmierz się z liszem Rezem Szeptem Mrozu w jego leżu.$B$BUżyj przeciw bestii mocy pamiątki – działaj nieustępliwie! Znieś ciosy, którymi miotająca się bestia na pewno cię zasypie. Nie ulegaj bólowi!$B$BGdy rytuał się dopełni, Rez znów stanie się śmiertelny. Wtedy właśnie trzeba go zabić. Powal go i zabierz jego ludzką głowę.', 'Odnajdź Reza Szepta Mrozu w Scholomancjum. Gdy go znajdziesz, użyj pamiątki związanej z duszą na jego nieumarłym obliczu. Jeśli zdołasz przywrócić mu śmiertelność, powal go i zdobądź Ludzką głowę Reza Szepta Mrozu. Zanieś głowę sędziemu Marduke\'owi.', '', 'Wróć do sędziego Marduke\'a nad Jeziorem Darrowmere na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5515, 'plPL', 'Torba okropności Krastinova', 'Wielki ciężar spadł nam z serc, $N, ale twoje zadanie jeszcze się nie skończyło. Pan Krastinova, Kirtonos, wciąż żyje.$B$BZanim jednak zmierzysz się z Kirtonosem, musisz najpierw zdobyć sposób, by go przywołać.$B$BPodobno to Jandice Barov przekazuje krew niewinnych od Krastinova do Kirtonosa.$B$BZnajdź ją w zatopionych katakumbach Scholomancjum i powal ją. Przynieś wszelkie wskazówki, jakie znajdziesz.', 'Odnajdź Jandice Barov w Scholomancjum i zniszcz ją. Zabierz z jej zwłok torbę okropności Krastinova. Zanieś torbę Evie Sarkhoff.', '', 'Wróć do Evy Sarkhoff nad Jeziorem Darrowmere na Zachodnich Plagowiskach.', '', '', '', '', 0),
(5721, 'plPL', 'Bitwa o Włości Darrow', 'Teraz, $N, weźmiesz udział w bitwie o Włości Darrow i ocalisz Josepha Redpatha.$B$BPołóż ten pakunek relikwii na rynku Włości Darrow, a duchy Włości Darrow powstaną. Przyłącz się do ich bitwy i dopilnuj, by stały się dwie rzeczy: Davil musi przeżyć śmierć Horgusa, a Redpath musi dożyć chwili, gdy ulegnie spaczeniu, a potem zostać pokonany.$B$BGdy pokonasz spaczonego Redpatha, jego duch zostanie ocalony. Porozmawiaj z nim, a potem wróć do jego córki Pameli.', 'Połóż pakunek relikwii na rynku Włości Darrow.$B$BNie dopuść do śmierci Davila Świetlistego Płomienia przed śmiercią Horgusa.$B$BNie dopuść do śmierci kapitana Redpatha, zanim pojawi się Redpath Spaczony.$B$BPokonaj Redpatha Spaczonego.$B$BPorozmawiaj z duchem Josepha Redpatha, gdy pojawi się na rynku, a potem porozmawiaj z Pamelą w jej domu.', '', 'Wróć do Pameli Redpath we Włościach Darrow na Wschodnich Plagowiskach.', 'Przyjmij przebaczenie Redpatha', '', '', '', 0),
(5846, 'plPL', 'O miłości i rodzinie', 'Gdy Taelan był dzieckiem, często odwiedzaliśmy Caer Darrow podczas rodzinnych wycieczek. Podczas naszej ostatniej wizyty artystka imieniem Renfray namalowała nasz portret na plaży. To moje najdroższe wspomnienie Taelana i Karandry. Bo właśnie wtedy, z żoną i synem w ramionach, poczułem więź miłości i rodziny, jakiej już nigdy nie miałem zaznać.$B$BJeśli ten obraz wciąż istnieje, musisz go odnaleźć.$B$BUdaj się na zrujnowaną wyspę Caer Darrow i sprawdź, czy ocalał obraz albo artystka.', 'Udaj się na wyspę Caer Darrow w południowo-środkowej części Plagowisk i poszukaj wszelkich wskazówek, gdzie może być obraz.', '', '', '', '', '', '', 0),
(5848, 'plPL', 'O miłości i rodzinie', 'Obraz... Przez lata wisiał na ścianie mojej pracowni – w koszarach Zakonu.$B$BGdy skończył się proces Tiriona, wiedziałam, że nie mogę dłużej trzymać obrazu na widoku. Ukryłam go w miejscu, w którym nikt nie pomyślałby go szukać.$B$BUdaj się do Stratholmu i przedostań się w głąb tego, co jest teraz Szkarłatnym Bastionem, a tam poszukaj obrazu przedstawiającego nasze bliźniacze księżyce. Zeskrob farbę, aż odsłonisz moje arcydzieło, „O miłości i rodzinie”.$B$BNiech Światłość prowadzi twoje czyny.', 'Udaj się do Stratholmu w północnej części Plagowisk. W Szkarłatnym Bastionie znajdziesz obraz „O miłości i rodzinie”, ukryty pod innym obrazem, przedstawiającym bliźniacze księżyce naszego świata.$B$BZanieś obraz Tirionowi Fordringowi.', '', 'Wróć do Tiriona Fordringa nad Rzeką Thondroril na Wschodnich Plagowiskach.', '', '', '', '', 0),
(5861, 'plPL', 'Odnajdź Myrandę', '$N, $gzrobiłeś:zrobiłaś; wszystko, o co dotąd prosiłem. Na drodze twojej misji odkupienia pozostał tylko jeden krok.$B$BMusisz dostarczyć zebrane przedmioty Taelanowi. Niestety, Taelan i jego szkarłatni krzyżowcy zaatakują cię, gdy tylko cię zobaczą.$B$BJest tylko jeden sposób, by przekazać moją wiadomość: podstęp i przebranie.$B$BNa południu znajdziesz grobowiec Uthera. Mieszka tam teraz moja stara i zaufana powierniczka, Myranda – odszukaj ją. Pokaż jej przedmioty, a ona ci pomoże.', 'Udaj się do Grobowca Uthera w południowej części Plagowisk. Pokaż Myrandzie Jędzy Dar Tiriona.', '', '', '', '', '', '', 0),
(5862, 'plPL', 'Szkarłatny podstęp', 'Jestem, można by rzec, iluzjonistką. Choć mogę stworzyć iluzję, która pozwoli ci dostać się do Żagiewia, ostrzegam: moje moce mają swoje granice.$B$BJeśli oddalisz się za bardzo od tych ziem, iluzja przestanie działać. Samo zaklęcie wymaga ode mnie wielkiego skupienia i mocy, dlatego mogę podtrzymywać jego działanie tylko przez krótki czas.$B$BPorozmawiaj ze mną ponownie, gdy będziesz $ggotów:gotowa;.', 'Porozmawiaj z Myrandą, by otrzymać Szkarłatną iluzję. Pod wpływem Szkarłatnej iluzji udaj się do Żagiewia i dostarcz Dar Tiriona najwyższemu lordowi Taelanowi Fordringowi.$B$BŻagiewie leży na północy, a Taelan powinien być w Twierdzy Mardenholde.', '', '', '', '', '', '', 0),
(5941, 'plPL', 'Powrót do Chromie', '$GZebrałeś:Zebrałaś; wiele relikwii z bitwy o Włości Darrow. Za każdym razem, gdy $gwracałeś:wracałaś; z kolejnymi, moje serce tęskniło za moją wioską... pragnęło ochronić ją przed jej losem.$B$BWiem, że to niemożliwe, ale Chromie, ta dziwna gnomka z Andorhalu, mówi mi, że to możliwe. Mówi, że możesz ocalić Włości Darrow!$B$BPoprosiła, żebym zebrał relikwie razem, a ty masz jej je zanieść. Powiedziała, że czeka na ciebie w zrujnowanej karczmie w Andorhalu.', 'Zanieś tobołek z relikwiami Chromie do Andorhalu.', '', '', '', '', '', '', 0),
(5944, 'plPL', 'We snach', 'Tak długo byłem marionetką Wielkiego Krzyżowca. Po co miałbym walczyć z tym, czym stała się Szkarłatna Krucjata? Minęły dziesięciolecia, a jednak to wspomnienia ojca – te cenne wspomnienia – utrzymywały mnie przy życiu.$B$BMiewam sny, $gnieznajomy:nieznajoma;. W tych snach mój ojciec jest ze mną. Stoi dumnie u mego boku, gdy zostaję przyjęty do Zakonu. Walczymy ramię w ramię z legionami Plagi. Przynosimy chwałę Przymierzu, Lordaeronowi.$B$BNie chcę już śnić.$B$BZaprowadź mnie do niego.', 'Wyprowadź Taelana Fordringa z Żagiewia.', 'Odkupienie?', 'Wróć do Tiriona Fordringa nad Rzeką Thondroril na Wschodnich Plagowiskach.', '', '', '', '', 0),
(6004, 'plPL', 'Niedokończone sprawy', 'Wysłano mnie na zwiad, żebym narobiła trochę szkód i oceniła siłę obrony Żagiewia. Niektórzy w Przymierzu uważają, że to miasteczko ma znaczenie nie tylko historyczne. Nie moja rzecz pytać, na czym to znaczenie polega, ale tak czy inaczej, nie jestem w stanie działać dalej, dopóki nie odpocznę.$B$BJeśli zechcesz, sowicie zapłacę za pomoc. Zacznij na południe stąd, od ich obozu przy niewielkiej barykadzie, którą tam postawili. Jeśli okażesz się $gdość silny:dość silna;, może pomożesz mi w moim głównym celu.', 'Zabij 2 szkarłatnych medyków, 2 szkarłatnych łowców, 2 szkarłatnych magów i 2 szkarłatnych rycerzy, a potem wróć do Kirsty Głębocień na Zachodnich Plagowiskach.', '', 'Wróć do Kirsty Głębocień na Zachodnich Plagowiskach.', '', '', '', '', 0),
(6023, 'plPL', 'Niedokończone sprawy', 'Moja prawdziwa misja polegała na osłabieniu wysuniętych sił Szkarłatnej Krucjaty, a potem przeniknięciu do Żagiewia, by oszacować ich liczebność. Wciąż nie jestem w stanie zrobić tego sama, więc może znów poproszę cię o pomoc, $N? Z informacji, które zebrałam, zanim mnie wykryto, wynika, że Krucjata ma dwóch ważnych członków, na których opierają się jej siły poza miastem: łowczynię Radley i kawalerzystę Durgena. Zabij ich, a zrobimy postępy. Powinni być na Przełęczy Żagiewia, poza samym miastem.', 'Zabij łowczynię Radley i kawalerzystę Durgena, a potem wróć do Kirsty Głębocień na Zachodnich Plagowiskach.', '', 'Wróć do Kirsty Głębocień na Zachodnich Plagowiskach.', '', '', '', '', 0),
(6025, 'plPL', 'Niedokończone sprawy', 'Co? Naprawdę? Chcesz wiedzieć więcej? Ale już tyle dla mnie $gzrobiłeś:zrobiłaś;, $N. Nie mogłabym prosić, żebyś w moim imieniu $gwszedł:weszła; do samego Żagiewia.$B$BNa pewno, $N? Żagiewie jest o wiele niebezpieczniejsze niż Przełęcz – nie mogę ci zapewnić żadnej ochrony ani nawet informacji o tym, co cię tam czeka.$B$BCóż, jeśli naprawdę chcesz pomóc, wejdź do miasta i znajdź jakieś wysokie miejsce, z którego dobrze je widać. Stamtąd oszacujesz ich liczebność i zdasz mi raport. Ale uważaj...', 'Wejdź do Żagiewia i znajdź wysoki punkt obserwacyjny, z którego zobaczysz miasto i oszacujesz siły Szkarłatnej Krucjaty, a potem wróć do Kirsty Głębocień na Zachodnich Plagowiskach.', 'Obejrzyj Żagiewie z wysokiego punktu obserwacyjnego', 'Wróć do Kirsty Głębocień na Zachodnich Plagowiskach.', '', '', '', '', 0),
(6165, 'plPL', '<NYI> <TXT> Szczątki arcymaga Timolaina', '', '', '', '', '', '', '', '', 0),
(6185, 'plPL', 'Wschodnie zarazy', 'Jak mówiłem, twoja pierwsza misja to zwiad. Nic wymyślnego, $N. Musisz udać się na Wschodnie Plagowiska i szukać wszelkich śladów tego Herolda Plagi.$B$BWypatruj też informacji o naszych zaginionych agentach. Musimy założyć, że nie żyją, a skoro nie żyją, to gdzieś muszą być ich zwłoki.$B$B<Flint z trudem przełyka ślinę.>$B$BWszyscy agenci WW:7 noszą tę odznakę.$B$B<Flint pokazuje ci swoją odznakę WW:7.>$B$BPrzynieś mi wszystkie takie, jakie znajdziesz.', 'Przeczesz Wschodnie Plagowiska w poszukiwaniu śladów „Herolda Plagi” i zaginionych agentów WW:7. Jeśli znajdziesz odznaki WW:7, zanieś je Flintowi Shadowmore\'owi do Obozu Zimnych Wichrów.', 'Herold Plagi zdemaskowany', 'Wróć do Flinta Shadowmore\'a w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(6569, 'plPL', 'Iluzje oka', 'A więc chcesz dołączyć do Czarnego Stada, co?$B$BStworzenie potrzebnej ci iluzji to drobnostka, ale składniki do wróżby niełatwo zdobyć. Wódz powierzył ci tę misję, więc Myranda musi uznać, że się do niej nadajesz.$B$BUdaj się do górnej cytadeli Iglicy Czarnej Góry i zabij tyle czarnych smoczych pomiotów, by wypełnić ich oczami jedną ze swoich sakw.$B$BWróć do Myrandy, gdy zbierzesz dość składnika.', 'Udaj się do Iglicy Czarnej Góry i zbierz 20 oczu czarnego smoczego pomiotu. Gdy wykonasz zadanie, wróć do Myrandy Jędzy.', '', 'Wróć do Myrandy Jędzy na Wzgórzu Smutku na Zachodnich Plagowiskach.', '', '', '', '', 0),
(8414, 'plPL', 'Rozpraszanie zła', 'Witaj, $N. Krzyżowcy tacy jak ty to mile widziany widok na tych opustoszałych rubieżach.$b$bTwoja święta siła jest potrzebna w walce z niekończącymi się zastępami nieumarłych. Musisz zebrać dużo kamieni Plagi i zanieść je arcykapłanowi Thel\'danisowi. Arcykapłan strzeże Grobowca Uthera na Wzgórzu Smutku, niedaleko stąd.$b$bKamienie Plagi może znaleźć tylko ten, kto nosi Zlecenie Argentowego Brzasku, więc jeśli jeszcze tego nie $gzrobiłeś:zrobiłaś;, porozmawiaj z oficer Czyste Serce.', 'Zbierz 20 kamieni Plagi sługi i zanieś je arcykapłanowi Thel\'danisowi na Zachodnich Plagowiskach.', '', 'Wróć do arcykapłana Thel\'danisa przy Grobowcu Uthera na Zachodnich Plagowiskach.', '', '', '', '', 0),
(8416, 'plPL', 'Nieaktywne kamienie Plagi', 'Zło zostało z kamieni wypędzone, $N.$b$bZnam plany dowódcy Ashlama, a on będzie potrzebował tylko jednego nieaktywnego kamienia. Zanieś mu go, byśmy mogli skąpać Plagę w sprawiedliwym ogniu.', 'Zanieś nieaktywny kamień Plagi dowódcy Ashlamowi Mężnopięściowi do Punktu Zimnych Wichrów.', '', '', '', '', '', '', 0),
(8418, 'plPL', 'Wykuwanie kamienia mocy', 'Teraz musimy połączyć nieaktywne kamienie Plagi i stworzyć broń, która rozbije szeregi nieumarłych. To nie jest błahe zadanie, $N. Tylko trolle z zatopionej świątyni mają tę rzadką magię, która potrafi obrócić zło czegoś przeciw niemu samemu.$b$bW świątyni trolle te znane są jako Gasher, Mijan, Zolo, Hukku, Zul\'Lor i Loro. Nie żałuj ich zepsutych dusz... nie są wolne od zła.', 'Zdobądź bursztynowe, niebieskie i zielone pióro wudu od trolli z Zatopionej Świątyni.', '', 'Wróć do dowódcy Ashlama Mężnopięścia w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(8714, 'plPL', 'Nestor Księżycowy Cios', '', '', '', '', '', '', '', '', 0),
(8722, 'plPL', 'Nestor Łąkobieg', '', '', '', '', '', '', '', '', 0),
(9445, 'plPL', '<NYI><TXT>Placeholder: Godna ofiara', '', 'Zdobądź Błogosławieństwo Uthera ze szczytu wieży strażniczej przy wejściu do Żagiewia i zanieś je <NPC> w Punkcie Zimnych Wichrów.', '', '', '', '', '', '', 0),
(9446, 'plPL', 'Grobowiec Światłodzierżcy', 'Skoro $godzyskałeś:odzyskałaś; Znak Światłodzierżcy, zostało tylko zwrócić go do Grobowca Uthera.$B$BCzy zechcesz mi towarzyszyć, gdy będę to robić? To niedaleko, a twoje towarzystwo sprawiłoby mi przyjemność. Potem możesz tu wrócić i opowiedzieć o wszystkim arcykapłance MacDonnell.$B$BCo ty na to, $N?', 'Odprowadź anachoretę Truuena do Grobowca Uthera na Zachodnich Plagowiskach. Potem porozmawiaj z arcykapłanką MacDonnell w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', 'Odprowadź anachoretę Truuena do Grobowca Uthera', 'Wróć do arcykapłanki MacDonnell w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(9474, 'plPL', 'Znak Światłodzierżcy', 'W tym krótkim czasie, który spędziłem w Azeroth, poznałem historie wielu jego bohaterów. Spośród nich wszystkich najwyżej stoi Uther Światłodzierżca. Bohater na wieki, który w końcu został zdradzony przez swojego najbardziej obiecującego ucznia, Arthasa.$B$BNa jego cześć chciałbym zwrócić do jego pobliskiego grobowca coś, co utracił. Podobno Szkarłatna Krucjata trzyma jedną z jego świętych relikwii na szczycie swojej wieży strażniczej przy bramach Żagiewia.$B$BProszę, $N, idź i ją odzyskaj.', 'Zdobądź Znak Światłodzierżcy i zanieś go anachorecie Truuenowi do Obozu Zimnych Wichrów na Zachodnich Plagowiskach.', '', 'Wróć do anachorety Truuena w Obozie Zimnych Wichrów na Zachodnich Plagowiskach.', '', '', '', '', 0),
(9901, 'plPL', 'Niedokończone sprawy', 'Pierwsza wyprawa wysłana przez Ligę zgłosiła, że natknęła się na olbrzymiego nietoperza-zarodnika, którego zaczęli nazywać Zarodnikoskrzydłym. Musieli uciekać w pośpiechu, więc nie mieli okazji go zabić, póki tu byli, i pomyślałem, że dokończę za nich robotę.$B$BZ resztek ich raportu wynika, że stwora można znaleźć w południowo-zachodniej części Martwego Grzęzawiska. Obrońca Idaar chyba wspominał, że to na północny wschód od Telredoru.', 'Poszukiwacz Conall w Telredorze chce, żebyś $gzabił:zabiła; Zarodnikoskrzydłego.', '', 'Wróć do Poszukiwacza Conalla w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(13097, 'plPL', 'Niedokończone sprawy', 'Choć to prawda, że prorok Akaliego nie będzie już nękał tego świata, wciąż zostało coś do zrobienia.$b$bWiększa część krwi Akaliego dała moc komuś innemu i to w nim kryje się prawdziwe niebezpieczeństwo.$b$bSzybko, $n, udaj się na północ od Gundraku, do Dubra\'Jin, i porozmawiaj z Tol\'marem. On wskaże ci dalszą drogę w tej sprawie.', 'Har\'koa chce, żebyś $gporozmawiał:porozmawiała; z Tol\'marem w Dubra\'Jin.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(211, 'plPL', 'Udało ci się! Araj... lisz wreszcie pokonany!$B$B$GOddałeś:Oddałaś; dziś Przymierzu ogromną przysługę, $N. Twoja odwaga i wytrwałość świadczą o tym, co znaczy być prawdziwym bohaterem. Proszę – przyjmij to jako znak, by wszyscy widzieli i wiedzieli, że $gzapewniłeś:zapewniłaś; Przymierzu zwycięstwo na wieki!', 0),
(4971, 'plPL', 'Teraz łatwiej naprawiać czas, dziękuję ci, $N. Choć możesz nie rozumieć w pełni skutków pękniętej linii czasu, doceniam, że rozumiesz, jak pilnie trzeba przeciwdziałać temu, co coraz bardziej podejrzewam o bycie niecnym dziełem Plagi.$B$BNie widzę nic złego w tym, by nagrodzić cię za pomoc, $gśmiertelniku:śmiertelniczko;. Twoje największe czyny dopiero przed tobą, a podarowanie ci błyskotki z pewnością nie zmieni twojego przeznaczenia. Za to twoja dalsza pomoc przydałaby się i mnie, i mojemu stadu...', 0),
(4972, 'plPL', 'Właśnie tego mi trzeba, $N. Dziękuję.$B$BPozwól, że godnie cię wynagrodzę. Możesz nie rozumieć, do czego miałoby ci się przydać takie urządzenie. Możesz nawet nie wiedzieć, czym ono właściwie jest. Niestety, nie mogę ci powiedzieć, kiedy okaże się najbardziej przydatne; wiedz tylko, że w pewnej chwili w przyszłości ten przedmiot, gdy go zużyjesz, może okazać się niezwykle użyteczny. Czy zechcesz go do tego czasu zachować... to już, $gprzyjacielu:przyjaciółko;, zależy od ciebie.', 0),
(4973, 'plPL', 'Raz jeszcze dziękuję ci za pomoc. Proszę, przyjmij ten dar. Choć nadal możesz nie wiedzieć, kiedy użyć takiego przedmiotu, może w przyszłości ścieżka czasu odsłoni przed tobą jego prawdziwe przeznaczenie. Można powiedzieć, że widziałam, jak ci się to przydarza, $N.', 0),
(4984, 'plPL', 'Ja... czuję, że dusze wilków, którym $gskróciłeś:skróciłaś; męki, zaznały spokoju. One – i ja – dziękujemy ci za miłosierne wyzwolenie.$B$BWilki nie są jedynymi, które cierpią w tym przeklętym miejscu, $N. Proszę, znów cię potrzebuję.', 0),
(4985, 'plPL', '„Wiem, że grizli zostały uśmiercone, a ich męka dobiegła końca. Ja... mam dla ciebie jeszcze jedną rzecz. Zapisałem to na... na tej gałęzi, czując, że mój czas w tym świecie dobiega końca.$B$BIstotnie... jestem u kresu. Dziękuję ci raz jeszcze, $gprzyjacielu:przyjaciółko;... stworzenia tej przeklętej krainy mogą spocząć... a teraz i ja spocznę”.$B$BPo tych słowach druid ciężko wzdycha, a potem rozlega się coś, co brzmi jak rzężenie konającego. Jego ciało leży bez ruchu na podłodze chaty.', 0),
(5021, 'plPL', 'Paczka w stodole, którą w innych okolicznościach można by przeoczyć, teraz wyraźnie odcina się od rozkładu i ruiny. Może to ta, o którą dopominał się duch Janice Felstone...', 0),
(5051, 'plPL', 'Podajesz złożony amulet szczęścia duchowi Janice Felstone. Gdy tylko go chwyta, dostrzegasz w niej niemal natychmiastową zmianę. Jej eteryczna postać migocze, a ona patrzy na ciebie jasnymi, choć smutnymi oczami.$B$B„$GUwolniłeś:Uwolniłaś; mnie... Nie będę już potrzebować tego amuletu. Proszę, weź go – może da ci ukojenie, jakie dał mnie”.', 0),
(5058, 'plPL', 'Dziennik o pożółkłych kartkach leży otwarty na ostatnim wpisie:$B$B„Nie wiem, co teraz będzie, skoro Harold się przemienił. Resztką sił zawlokłam go do jedynego miejsca, jakie znalazłam, gdzie dało się go szczelnie zamknąć i zatrzymać. Klucz ukryłam przy sobie i modlę się, żeby to wystarczyło...$B$BMam nadzieję, że zdołam się stąd wydostać, ale potrzebuję na to pieniędzy. Chyba wszystkie nasze rzeczy są w szafce... a teraz, jak o tym myślę, czy to nie Harold nosi przy sobie klucz?$B$BPrześpię się z tym, jestem śmiertelnie zmęczona”.', 0),
(5059, 'plPL', 'Kluczem znalezionym przy szkielecie dawnej pani Dalson otwierasz drzwi wychodka. Wyskakuje z niego żądny krwi ghul, uwięziony w środku nie wiadomo jak długo.$B$BMrożący krew w żyłach wrzask, jakim ghul wita twoje pojawienie się, nie pozostawia wątpliwości: dawnego rolnika Dalsona nie da się już ocalić.', 0),
(5060, 'plPL', 'Klucz zabrany z ghulich szczątków rolnika Dalsona idealnie pasuje do zamka. Drzwiczki szafki otwierają się, odsłaniając kilka nienaruszonych przedmiotów, które wyglądają na całkiem cenne.', 0),
(5092, 'plPL', 'Misja wykonana, $N! Dobra robota, naprawdę dobra robota.$B$BPozwól, że wynagrodzę twoją dotychczasową pracę monetą ze skarbca Wichrogrodu. Radzę wydać ją na sprzęt, który pomoże ci w następnej misji... tej, która zaprowadzi cię do samych ruin Andorhalu.$B$BBądź $ggotów:gotowa;! Bądź $gczujny:czujna;!', 0),
(5097, 'plPL', 'Moi kapłani donoszą, że nasze namierniki odbierają niezwykle silne sygnały ze wszystkich czterech wież! Śmiem twierdzić, że $gwykonałeś:wykonałaś; kolejną misję z całkowitym i pełnym powodzeniem! Znów dobra robota, $N!$B$BWieże są oznaczone, więc przygotowania do ataku zakończone. Nadszedł czas, by uderzyć na Plagę!', 0),
(5142, 'plPL', 'Dzień dobry. Jestem Pamela, a ty jak masz na imię?', 0),
(5152, 'plPL', '$GWidziałeś:Widziałaś; Pamelę? Jak się czuje? Żyje?? Och, nie! Biedna Pamela! Była taka mała i taka radosna...$B$BNie wie, co się stało z jej ojcem, prawda? Z moim bratem, Josephem?$B$BNie... nie mogłaby zrozumieć, co się stało z Josephem. A nawet gdyby mogła, nie mam serca jej tego powiedzieć...', 0),
(5153, 'plPL', 'Co to? Obrączka ślubna? Pokaż...$B$BAch! Ta obrączka zdobiła niegdyś dłoń wielkiego człowieka, ale w jego przeszłości kryje się wiele tragedii.$B$BChcesz mu pomóc? Teraz jest już dla niego o wiele za późno... ale może zdołamy mu pomóc w przeszłości!', 0),
(5154, 'plPL', 'Brawo, $gznalazłeś:znalazłaś; ją!$B$B$GCzytałeś:Czytałaś;? Czy pojawia się w niej Joseph Redpath? Jeśli tak, może zdołamy go ocalić!$B$BAch. Kroniki Włości Darrow opowiadają bardzo niepokojącą historię. Piszą, że podczas bitwy Joseph Redpath uległ spaczeniu i dołączył do szeregów Plagi! Potem zdradził obrońców Włości Darrow.$B$BTo zły los. Jeśli się da, powinniśmy spróbować go zmienić, nie sądzisz?', 0),
(5162, 'plPL', 'Jestem Jeziba, przez wielu zwany Rzeźbiarzem. Nie rzeźbię jednak posągów, lecz bohaterów.$b$b', 0),
(5164, 'plPL', 'Większość tej księgi to setki, setki stron wypełnionych bełkotliwym tekstem i symbolami.', 0),
(5166, 'plPL', 'Czy jeszcze nie rozumiesz? Podróż była celem. Czy nie czujesz blizn po bitwach? Bólu, który $gprzeszedłeś:przeszłaś;?$B$BSkoro $gprzetrwałeś:przetrwałaś; tę próbę, masz w sobie więcej mocy. O wiele więcej. Ten napierśnik jest tylko odbiciem twoich wrodzonych zdolności.', 0),
(5167, 'plPL', 'Gdy wejdziesz do ich sal, wyczują w tobie swoich pobratymców, $N. Zmiażdż ich ich własnym strachem!', 0),
(5210, 'plPL', 'Co to za księga? Kroniki Włości Darrow? To był mój dom przed wojną... mój dom przed bitwą, która go zniszczyła! Czemu mi ją $gprzyniosłeś:przyniosłaś;?$B$BAle spójrz tutaj! Na końcu są strony, które opowiadają o dniach po bitwie! Jest tu fragment o mnie! I jeden o moim bracie Josephie! Czy ta księga mówi prawdę?$B$BMusimy odkryć prawdę!', 0),
(5215, 'plPL', 'Niech moc Światłości świeci nad tobą w tych mrocznych czasach, $N. Z radością będę koordynować nasz plan sabotażu kotłów Plagi.$B$BNaszym celem jest zmiana składu zarazy wytwarzanej przez kotły tak, by szkodziła samej Pladze. Aby tego dokonać, musisz zdobyć dostęp do każdego z czterech kotłów na Zachodnich Plagowiskach.$B$BBądź $ggotów:gotowa;, $gbohaterze:bohaterko;, bo czeka cię chwalebna bitwa z plugawą Plagą!', 0),
(5216, 'plPL', 'Klucz zabrany władcy kotła Żółciopaszczowi idealnie pasuje do panelu dostępowego. Z otwartego panelu bucha odrażający smród, a we wnętrzu kotła wiruje nieznana mieszanina stężonych substancji.$B$BJest tu mały kurek, pod który butelka mieści się wystarczająco dobrze, byś $gmógł:mogła; pobrać próbkę dla arcykapłanki MacDonnell w Punkcie Zimnych Wichrów.', 0),
(5217, 'plPL', 'Dobra robota, $N – alchemik Arbington przeanalizuje to w mgnieniu oka i opracuje przeciwśrodek, który wprowadzimy do kotła. Jeśli zdołamy wypompować go w powietrze w wystarczającej ilości, może uda się osłabić całą tutejszą Plagę.$B$BTo bez wątpienia będzie długa mordęga; będziemy musieli ciągle uderzać na te kotły i dodawać do ich mieszanki nasze odczynniki. Ale jeśli wytrwamy, to gdy przyjdzie czas bitwy, będziemy mieć nad Plagą ogromną przewagę!', 0),
(5218, 'plPL', 'Po dodaniu odczynników do mieszanki kotła chmura, którą z siebie wyrzuca, zaczyna zmieniać barwę i konsystencję. Słudzy Plagi znajdujący się choćby w pobliżu kotła wyraźnie się cofają, gdy w otoczeniu pojawiają się nowe składniki.', 0),
(5219, 'plPL', 'Makabryczny klucz znaleziony przy władcy kotła gładko wsuwa się w dziurkę, po czym znika, zapewniając ci stały dostęp. W poskręcanych rurach pod konstrukcją kotła pulsuje gęsta, surowa posoka.$B$BJest tu mały kurek, pod który butelka mieści się wystarczająco dobrze, byś $gmógł:mogła; pobrać próbkę dla arcykapłanki MacDonnell w Punkcie Zimnych Wichrów.', 0),
(5220, 'plPL', 'Ach, jest tu mnóstwo materiału do badań. Dobra robota, $N!$B$BNa razie następny krok należy do nas. Musimy przygotować listę odczynników, które po połączeniu z tym, co już jest w kotle, zadziałają przeciw niemu.$B$BJedyny sposób, by je wprowadzić, to wrzucić odczynniki bezpośrednio do kotła. Alchemik Arbington powie ci o tym więcej, więc porozmawiaj z nim przy najbliższej okazji.', 0),
(5221, 'plPL', 'Po dodaniu odczynników do mieszanki kotła chmura, którą z siebie wyrzuca, zaczyna zmieniać barwę i konsystencję. Słudzy Plagi znajdujący się choćby w pobliżu kotła wyraźnie się cofają, gdy w otoczeniu pojawiają się nowe składniki.', 0),
(5222, 'plPL', 'Klucz władcy kotła otwiera panel dostępowy tego kotła, po czym znika – tak jak klucze do dwóch poprzednich kotłów, z którymi się $gzmierzyłeś:zmierzyłaś;. Pod platformą kotła gwałtownie kłębi się cuchnąca zgnilizną substancja.$B$BJest tu mały kurek, pod który butelka mieści się wystarczająco dobrze, byś $gmógł:mogła; pobrać próbkę dla arcykapłanki MacDonnell w Punkcie Zimnych Wichrów.', 0),
(5223, 'plPL', 'Kolejna znakomicie wykonana misja, $N! Mamy już trzy kotły, które możemy obrócić przeciw Pladze. Gdyby nekromancka władza Kel\'Thuzada nad tymi ziemiami nie była tak silna, śmiem twierdzić, że $gzdołałbyś:zdołałabyś; całkiem je unieszkodliwić!$B$BAlchemik Arbington przygotuje raport o tym, czego ten kocioł – i pozostałe przejęte kotły – wymaga, byśmy mogli wprowadzić przeciwśrodek na zarazę. A teraz pora przejąć ostatni kocioł na zachodzie!', 0),
(5224, 'plPL', 'Po dodaniu odczynników do mieszanki kotła chmura, którą z siebie wyrzuca, zaczyna zmieniać barwę i konsystencję. Słudzy Plagi znajdujący się choćby w pobliżu kotła wyraźnie się cofają, gdy w otoczeniu pojawiają się nowe składniki.', 0),
(5225, 'plPL', 'Klucz władcy kotła Duszogniewa rozpada się w pył, gdy tylko dotyka zamka panelu dostępowego u podstawy platformy kotła. W środku coś cicho szczęka, a panel otwiera się, odsłaniając kolejne gęste toksyny w konstrukcji kotła.$B$BJest tu mały kurek, pod który butelka mieści się wystarczająco dobrze, byś $gmógł:mogła; pobrać próbkę dla arcykapłanki MacDonnell w Punkcie Zimnych Wichrów.', 0),
(5226, 'plPL', 'Gratulacje, $N, $gotworzyłeś:otworzyłaś; dla nas ostatni kocioł! Alchemik Arbington wkrótce ustali, jakich odczynników wymaga mieszanka w tym kotle.$B$BCo do ciebie – jestem pewna, że dowódca Mężnopięść zechce osobiście podziękować ci za pomoc, jakiej nam $gudzieliłeś:udzieliłaś;. Bez ciebie nasza walka z Plagą byłaby niemal beznadziejna. Dziękuję ci, $gbohaterze:bohaterko;!', 0),
(5227, 'plPL', 'Po dodaniu odczynników do mieszanki kotła chmura, którą z siebie wyrzuca, zaczyna zmieniać barwę i konsystencję. Słudzy Plagi znajdujący się choćby w pobliżu kotła wyraźnie się cofają, gdy w otoczeniu pojawiają się nowe składniki.', 0),
(5237, 'plPL', '$N, twoja udana przeróbka kotłów to dla nas ogromne zwycięstwo!$B$B<Dowódca odchrząkuje i zaczyna donośnie grzmieć.>$B$BNiech słyszą wszyscy obecni: za służbę dla Królestwa Wichrogrodu i dla Przymierza, daleko wykraczającą ponad obowiązek – w obliczu przytłaczającej przewagi wroga i niewiarygodnego niebezpieczeństwa, dodam – niech $N przyjmie ode mnie ten dar, a ja wyrażam $gmu:jej; naszą dozgonną wdzięczność jako $gprawdziwemu bohaterowi:prawdziwej bohaterce; Przymierza. Wiwat!', 0),
(5344, 'plPL', 'Cóż za chwalebny dzień! Wreszcie ta skaza na rodzie Barovów usunięta, a moja fortuna bezpieczna!$B$BWeź to i zejdź mi z oczu, $gchłopie:chłopko;.', 0),
(5382, 'plPL', 'Czuję, jak mój duch się leczy, $N. $GOddałeś:Oddałaś; mojemu mężowi i mnie wielką przysługę, ale jestem pewna, że jest jeszcze wiele do zrobienia.', 0),
(5384, 'plPL', 'Wraz ze śmiercią Kirtonosa zamyka się rozdział okropnej historii Scholomancjum. Jest jednak jeszcze wiele do zrobienia. Inni tutaj wiedzą już o twoich odważnych czynach. Weź to, $N. To cząstka naszej własnej esencji. Pozwoli ci porozumiewać się z innymi zagubionymi duszami Caer Darrow.', 0),
(5401, 'plPL', 'Wszyscy, którzy walczą ze złem w imieniu Argentowego Brzasku, muszą nosić nasze Zlecenie. Dzięki niemu zyskujesz prawo do nagród oferowanych przez naszych kwatermistrzów.$B$BGdy nosisz Zlecenie, możesz zdobywać kamienie Plagi z zabitych sług Plagi; to insygnia, które czasem przy sobie mają. Zdobywaj je i przynoś mi. Za każdy oddany komplet otrzymasz nasz znak bohaterstwa – żeton męstwa Argentowego Brzasku.$B$BWypełnij swoje przeznaczenie, $N – dołącz do walki już dziś!', 0),
(5408, 'plPL', 'Gratulacje, $N – z przyjemnością przyznaję ci żeton męstwa Argentowego Brzasku!\n\nŻetony służą dwóm celom. Po pierwsze – można nimi umocnić swoją pozycję w Argentowym Brzasku, co może otworzyć przed tobą możliwości i nagrody zarezerwowane dla naszych szanowanych i czczonych sojuszników. Po drugie – można je oddać naszym kwatermistrzom, razem z monetą, jako zapłatę za niektóre z najcenniejszych przedmiotów Brzasku.\n\nCokolwiek postanowisz, wiedz, że zasługujesz na swoje Zlecenie. Dobra robota!', 0),
(5461, 'plPL', 'Wątpiłem, czy taki przedmiot w ogóle istnieje. To z pewnością otwiera przed nami niezwykłą szansę – której nie wolno nam zmarnować.$B$BPrzygotuj się, $N, bo to, o co zaraz cię poproszę, zaprowadzi cię w otchłań piekła.', 0),
(5462, 'plPL', '<Leonid ogląda pamiątkę.>$B$BTwój kłopot budzi wspomnienia, które miałem nadzieję, że już nigdy nie powrócą.', 0),
(5465, 'plPL', 'Byłem pewien, że dołączysz do mnie jako kolejny nieszczęsny duch.', 0),
(5466, 'plPL', 'Dziesięć tysięcy dusz krzyczy jednym głosem, $N! $GZadałeś:Zadałaś; śmiertelny cios Pladze i jej panom.', 0),
(5515, 'plPL', 'Torba okropności!', 0),
(5533, 'plPL', 'Bądź $gpozdrowiony:pozdrowiona;, $N. Sporą część moich ostatnich badań poświęciłem Scholomancjum i chyba wiem, jak możesz zdobyć klucz... taki, który przepuści cię przez frontowe drzwi.$B$BMogę sobie tylko wyobrażać, jakie okropieństwa kryją się w środku, $N. Czasem nie wiem, jak wy, bohaterowie, to robicie...', 0),
(5537, 'plPL', 'Nadadzą się, $N! Teraz moja kolej – nasycę je odpowiednim hartem, żeby przetrwały morderczy proces kucia, który je w końcu czeka.$B$BNastępny krok to zdobycie odpowiedniej formy na klucz. Znam goblińskiego kowala w Tanaris, który robił już formy na podobnie makabryczne przedmioty. Pracuje dla tego, dla kogo zwykle pracują gobliny – dla tego, kto da więcej.', 0),
(5721, 'plPL', 'Walka się skończyła! Słyszałam, jak tatuś do mnie szeptał. Przepędził wszystkie duchy i mówi, że wraca do domu! Tak się cieszę!$B$BPowiedział też, że mam cię ugościć, jeśli przyjdziesz do naszego domu, więc zrobiłam herbatę!$B$BMam nadzieję, że lubisz dużo cukru!', 0),
(5846, 'plPL', 'Jakżebym mogła zapomnieć? Wiele duchów na tej wyspie jest przeklętych – muszą wciąż na nowo przeżywać ostatnie szczęśliwe wspomnienie sprzed tragicznego końca.$B$BJa także jestem przeklęta, ale nie tak jak oni – jestem jedną z nielicznych, które pamiętają wszystko...$B$BMoże to, o co mnie prosisz, jest powodem, dla którego nawiedzam te ruiny. Może to, co ci powiem, mnie uwolni.', 0),
(5848, 'plPL', '<Na widok obrazu Tirion omal nie osuwa się na ziemię.>$b$b<Zaczyna szlochać, niemal w amoku.>', 0),
(5861, 'plPL', 'Byłam najbardziej zaufaną doradczynią Tiriona, gdy był lordem Mardenholde. Otwarcie sprzeciwiłam się wyrokowi Zakonu Srebrnej Dłoni i zostałam wygnana za swoje zuchwalstwo.$b$bWiele w życiu przeszedł – wiele bólu serca i rozczarowań. Czy jesteś $ggotów:gotowa; naprawić krzywdy wyrządzone Fordringom?', 0),
(5862, 'plPL', 'Co to jest, żołnierzu?$b$b<Taelan otwiera skrzynkę i zaczyna przeglądać jej zawartość.>$b$bTo... to nie może być prawda. Ale wszystko, co mi $gpokazałeś:pokazałaś;...$b$b<Taelan pada na jedno kolano, jego serce bije coraz szybciej. Gniew wieków zaraz spadnie na to miasto.>', 0),
(5903, 'plPL', 'Nadadzą się świetnie, $N. Dziękuję. Tylko na nie spójrz... tyle ich, wszystkie stłoczone razem. Prawie żal mi Krucjaty, ale z drugiej strony ten tartak nigdy nie był ich, prawda?', 0),
(5941, 'plPL', 'Ach tak, oto one. Razem splatają potężne zaklęcie – takie, które wskrzesi duchy Włości Darrow.$B$BDzięki temu zaklęciu, i odrobinie szczęścia, możemy ocalić Josepha Redpatha!', 0),
(5944, 'plPL', 'Śmierć mojego syna z rąk tych potworów nie ujdzie im na sucho. Niech pocieszy cię to, że Zakon odrodził się na nowo.$b$bObejmuję teraz miejsce najwyższego lorda nowego Zakonu Srebrnej Dłoni.$b$bTe rzeczy z mojej przeszłości – to wszystko, co mogę ci ofiarować za wszystko, co $gzrobiłeś:zrobiłaś;. Proszę, przyjmij je jako symbol mojej wdzięczności; przez lata dobrze mi służyły.$b$bObyśmy spotkali się znowu, w lepszych czasach, i powspominali dawno minione dni... zacięte bitwy... odkupione sny.', 0),
(6004, 'plPL', 'Dobra robota, $N. Aż trudno uwierzyć, że tak szybko się z nimi $guporałeś:uporałaś;. Dziękuję.$B$BNie spotkałam jeszcze nikogo, kto pochwalałby Szkarłatną Krucjatę i jej metody. Wierzę w Światłość jak każdy w Wichrogrodzie, ale oni pokazali, że chcą tylko zabijać każdego, kto nie jest wierny ich ruchowi... nawet niewinnych.', 0),
(6023, 'plPL', 'Dziękuję, $N. $GPomogłeś:Pomogłaś; mi bardziej, niż mogłam się spodziewać. Tutejsze powietrze zdaje się wysysać ze mnie wolę. Jestem zmęczona i czuję, że im dłużej tu jestem, tym jest gorzej.$B$BNie bardzo wiem, jak mam przeniknąć do samego Żagiewia i zdać raport o sile Szkarłatnej Krucjaty.$B$BAle to inna sprawa. Zanim odejdziesz, weź to... jako zapłatę za pomoc. Jeszcze raz dziękuję.', 0),
(6025, 'plPL', 'Udało ci się, $N! Dziękuję!$B$BWrócę do Elling... to znaczy do Wichrogrodu, gdy tylko będę mogła. Proszę, weź tę monetę, to najmniejsze, co mogę dla ciebie zrobić. Przynosisz chlubę swojemu ludowi, $N. Dziękuję i powodzenia.', 0),
(6028, 'plPL', 'Gregor to człowiek bardzo zaradny. Od dłuższego czasu ma do czynienia z Kartelem Parochlebców i stał się znawcą „sztuki” negocjacji z goblinami. Choć prawdą jest, że gobliny są lojalne przede wszystkim wobec tych, którzy mają najgrubsze sakiewki, znają też i szanują wartość dyplomacji. Choćby dlatego, że zapewnia im stałych klientów...$B$BTak czy inaczej, Argentowy Brzask docenia twój wysiłek. Proszę, przyjmij to z naszymi podziękowaniami.', 0),
(6185, 'plPL', 'Rutger. Fredo. Turyen. Wszyscy... martwi...$B$B<Flint mocno ściska odznaki.>$B$BGdzie byli? $GDowiedziałeś:Dowiedziałaś; się czegoś więcej o tym potworze, Heroldzie Plagi?', 0),
(6389, 'plPL', 'Ha! Dziękuję, $N! Udało ci się! Duch mojego ojca może teraz spocząć, a ja mogę żyć w spokoju.$B$BJeszcze raz dziękuję. Jeśli mogę coś dla ciebie zrobić, po prostu powiedz.', 0),
(6569, 'plPL', 'Pokaż Myrandzie.$B$BO tak, nadadzą się świetnie.$B$BZ tych składników Myranda stworzy dla ciebie medalion, który wywoła iluzję zdolną oszukać odźwiernego Czarnego Stada.', 0),
(8414, 'plPL', 'Rozpraszanie zła z kamienia Plagi jest ryzykowne, bo przyciąga uwagę nieumarłych z niezliczonych mil. Ale jesteś $gsilny:silna; w Światłości, $N, i nie obawiam się o ciebie...', 0),
(8416, 'plPL', '$GZrobiłeś:Zrobiłaś;, o co prosiłem, bez zadawania pytań, $N.$b$bWygląda na to, że zdobyliśmy wzajemne zaufanie. Może teraz mogę zdradzić ci nasz plan dokładniej.', 0),
(8418, 'plPL', 'Doskonale, $N. Mógłbym powiedzieć, że jestem zaskoczony, ale wiedziałem bez cienia wątpliwości, że nas nie zawiedziesz.$B$BTo dla mnie zaszczyt wręczyć ci jeden ze Świętych kamieni mocy. Używaj go dobrze.', 0),
(9446, 'plPL', 'Światłodzierżca ukazał się przed tobą? To niesamowite! I to ty to $gumożliwiłeś:umożliwiłaś;, bezinteresownie pomagając anachorecie.$B$BJeśli choć połowa opowieści jest prawdziwa, Uther był wielkim człowiekiem. I tak jak on jesteś $gprawdziwym bohaterem:prawdziwą bohaterką; dla wszystkich dobrych ludzi Azeroth, $N!', 0),
(9474, 'plPL', 'Dziękuję, $N! Odzyskanie tego świętego symbolu wiele znaczy dla mnie i dla innych, którzy czczą pamięć Uthera Światłodzierżcy.', 0),
(11756, 'plPL', 'Zbezcześć wielkie ognisko Przymierza na Zachodnich Plagowiskach!', 0),
(11827, 'plPL', 'Uczcij płomień Zachodnich Plagowisk!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(211, 'plPL', 'Znasz swoje zadanie, $N. Czy masz odłamek filakterii lisza jako dowód, że zostało wykonane?', 0),
(4971, 'plPL', 'Pasożyty czasu to powszechna przypadłość wszędzie tam, gdzie ktoś majstrował przy biegu czasu. Wyczuwam, że jest ich tu wiele, i to mnie niepokoi.$B$BWypłoszenie tych, które zdołasz znaleźć, pomoże mi lepiej zapanować nad pogarszającą się sytuacją czasową. Wyczuję, gdy to się uda.', 0),
(4972, 'plPL', 'Czasowe drobiazgi, których szukam, to proste urządzenia. Głównie zegarki, których wskazówki na zawsze zastygły w chwili, gdy zaraza po raz pierwszy spustoszyła Andorhal.$B$BCzas nigdy się nie kończy, a zegarki, które mi przyniesiesz, nieuchronnie zostaną odliczone z powrotem tam, skąd pochodzą... to znaczy, dopóki trwają tu te zakłócenia.', 0),
(4973, 'plPL', 'Zegarki z Andorhalu, podobnie jak wielki zegar na ruinach ratusza, zastygły w czasie na godzinie trzeciej. Właśnie wtedy zaraza w pełni rozlała się po mieście i wydusiła z niego życie.$B$BChoć wszyscy możemy żałować tego, co stało się tamtego dnia, ukształtowało to bieg czasu, jaki postrzegacie wy, śmiertelni. Brązowe Stado musi wytrwać w ochronie linii czasu!', 0),
(4984, 'plPL', 'Wilki zarażone zarazą trzeba uśmiercić, $N. Choroby, którą noszą, nie da się wyleczyć. Próbowałem... próbowałem, aż sam uległem zarazie.', 0),
(4985, 'plPL', 'Słyszę twoje kroki, $N. Wzrok mnie opuścił, ale wciąż potrafię wyczuć, co dzieje się wokół mnie. Czy $gskróciłeś:skróciłaś; męki chorych grizli?', 0),
(5051, 'plPL', 'John, nie daj się ghulom... nie daj im mnie dopaść... wstrętne ghule... nasz amulet nas ochroni.', 0),
(5059, 'plPL', 'Drzwi wychodka zaczęły pękać przy krawędziach framugi, jakby ktoś raz po raz i bez ustanku próbował je wyważyć. Obecnie są szczelnie zamknięte od zewnątrz.$B$BGdy szarpiesz drzwiami, ze środka dobiega gardłowy jęk! Cokolwiek tam siedzi, z pewnością nie brzmi przyjaźnie.', 0),
(5060, 'plPL', 'Stoi przed tobą niezwykle solidna szafka, zamknięta na wbudowany zamek. Jej front jest głęboko porysowany i poznaczony. Można przypuszczać, że to ślady licznych, gwałtownych i nieudanych prób wydarcia sekretów, które szafka wciąż skrywa przed wzrokiem.$B$BJeśli chcesz ją otworzyć, musisz znaleźć klucz.', 0),
(5092, 'plPL', 'Przygotuj się na najgorsze, $N – zbierz wszystkie siły. Zadanie przed nami nie będzie łatwe. Gdy tu zbieramy siły, by w końcu uderzyć na Plagę, ty będziesz w naszej straży przedniej, która poniesie walkę do wroga! Twoja misja na Wzgórzu Smutku otworzy nam drogę do zwycięstwa!', 0),
(5097, 'plPL', 'Oznaczone wieże staną się najważniejszymi celami naszego ataku na Andorhal. Podejrzewam, że gdy je zneutralizujemy, ujawni się główne zagrożenie Andorhalu. Od tej chwili czeka nas otwarta walka o kontrolę nad miastem!$B$B$GWróciłeś:Wróciłaś;, by zameldować o sukcesie, tak? Nie zapomnij też o pochodni sygnałowej; musimy pilnować naszego sprzętu.', 0),
(5153, 'plPL', 'Twoja wizyta jest jakoś dziwnie na czasie. Nie przybywasz chyba z przyszłości, co?', 0),
(5166, 'plPL', '$GWybrałeś:Wybrałaś; mądrze.', 0),
(5167, 'plPL', 'Nikt jeszcze nie wykonał takiego przedmiotu!', 0),
(5210, 'plPL', 'Przybywasz z zachodu? Jak się ma reszta Lordaeronu? Wiem, że Andorhal przepadł, ale czy Plaga dotarła już do pięknego Tirisfal?', 0),
(5216, 'plPL', 'Panel dostępowy kotła jest solidnie zamknięty. Aby go otworzyć, musisz znaleźć klucz.\n', 0),
(5217, 'plPL', 'Witaj z powrotem w Obozie Zimnych Wichrów, gdzie jest względnie bezpiecznie, $N. Jakie postępy w sprawie kotłów masz do zameldowania?', 0),
(5218, 'plPL', 'Stoi przed tobą kocioł zarazy Plagi, wyrzucający w powietrze ogromne ilości toksyn. U podstawy rozległej platformy kotła znajduje się mały, niepozorny panel dostępowy.$B$BPonieważ już $gpokonałeś:pokonałaś; władcę kotła i $gzdobyłeś:zdobyłaś; jego klucz, możesz swobodnie dodać do kotła odpowiednie odczynniki, by powstał przeciwśrodek na zarazę.', 0),
(5219, 'plPL', 'Panel dostępowy kotła jest solidnie zamknięty. Aby go otworzyć, musisz znaleźć klucz.', 0),
(5220, 'plPL', 'Wiemy, że każdy kocioł używa innej mieszanki odczynników do wytwarzania toksyny szerzącej zarazę; wiemy też, że dla każdego kotła musimy opracować osobny przeciwśrodek. Twoja próbka z Łez Dalsona będzie kluczem do ustalenia, jakich odczynników wymaga ten kocioł.', 0),
(5221, 'plPL', 'Stoi przed tobą kocioł zarazy Plagi, wyrzucający w powietrze ogromne ilości toksyn. U podstawy rozległej platformy kotła znajduje się mały, niepozorny panel dostępowy.$B$BPonieważ już $gpokonałeś:pokonałaś; władcę kotła i $gzdobyłeś:zdobyłaś; jego klucz, możesz swobodnie dodać do kotła odpowiednie odczynniki, by powstał przeciwśrodek na zarazę.', 0),
(5222, 'plPL', 'Panel dostępowy kotła jest solidnie zamknięty. Aby go otworzyć, musisz znaleźć klucz.', 0),
(5223, 'plPL', 'Gdy przeanalizujemy próbkę pobraną z kotła w Wijącym się Nawiedzisku, zyskamy trzecią drogę, by uderzyć w Plagę niszczycielskim przeciwśrodkiem!', 0),
(5224, 'plPL', 'Stoi przed tobą kocioł zarazy Plagi, wyrzucający w powietrze ogromne ilości toksyn. U podstawy rozległej platformy kotła znajduje się mały, niepozorny panel dostępowy.$B$BPonieważ już $gpokonałeś:pokonałaś; władcę kotła i $gzdobyłeś:zdobyłaś; jego klucz, możesz swobodnie dodać do kotła odpowiednie odczynniki, by powstał przeciwśrodek na zarazę.', 0),
(5225, 'plPL', 'Panel dostępowy kotła jest solidnie zamknięty. Aby go otworzyć, musisz znaleźć klucz.', 0),
(5226, 'plPL', 'Na Plonach Gahrrona stoi ostatni kocioł, do którego musimy zdobyć dostęp – tutaj, na wschodzie. Gdy zdobędziemy próbkę zarazy, którą wyrzuca, będziemy mogli wprowadzać nasze odczynniki do otoczenia przez cztery osobne naczynia! Pladze trudno będzie odciąć nas od wszystkich czterech, nawet z potęgą Kel\'Thuzada za plecami.', 0),
(5227, 'plPL', 'Stoi przed tobą kocioł zarazy Plagi, wyrzucający w powietrze ogromne ilości toksyn. U podstawy rozległej platformy kotła znajduje się mały, niepozorny panel dostępowy.$B$BPonieważ już $gpokonałeś:pokonałaś; władcę kotła i $gzdobyłeś:zdobyłaś; jego klucz, możesz swobodnie dodać do kotła odpowiednie odczynniki, by powstał przeciwśrodek na zarazę.', 0),
(5343, 'plPL', 'Pochyl głowę w mojej obecności. W końcu jestem szlachcicem, a ty – $gchłopem:chłopką; bez miedziaka przy duszy.', 0),
(5344, 'plPL', 'Chcesz przecież zapłaty, prawda?', 0),
(5382, 'plPL', 'Rzeźnika trzeba powstrzymać!', 0),
(5384, 'plPL', 'Uważaj, Kirtonos to doświadczony wojownik.', 0),
(5461, 'plPL', 'Pamiątka wspomnień to rzadkie znalezisko, $N.', 0),
(5462, 'plPL', 'Nie zadawaj pytań, na które nie chcesz znać odpowiedzi.', 0),
(5465, 'plPL', 'Czy $gdokonałeś:dokonałaś; niemożliwego?', 0),
(5466, 'plPL', 'Dźwigasz brzemię dziesięciu tysięcy niespokojnych dusz, $N.', 0),
(5515, 'plPL', '<Postać Evy to się wyostrza, to rozmywa.>', 0),
(5537, 'plPL', 'Choć brzmi to ponuro, potrzebujemy sporego zapasu odpowiednich fragmentów szkieletów na zewnętrzną warstwę klucza. Nie bez powodu ten wytrych ma w sobie tyle kości.', 0),
(5721, 'plPL', 'Chyba słyszałam duchy na dworze. Szepczą mi straszne rzeczy...', 0),
(5848, 'plPL', 'Obraz, $N. Masz obraz?', 0),
(5861, 'plPL', 'Wiedziałam, że ten dzień nadejdzie.', 0),
(5862, 'plPL', 'Jesteś z posiłków z Dłoni Tyra?', 0),
(5903, 'plPL', '$GZnalazłeś:Znalazłaś; kopce termitów, $N? Słyszałem, że są w całym Plagowym Lesie.', 0),
(5941, 'plPL', 'Kontaktowałam się z twoim przyjacielem Carlinem. Bardzo cierpi z powodu zagłady swojej wioski, ale wyraża się o tobie w samych superlatywach i wie, że potrafisz wszystko naprawić.$B$BOch, ale odbiegam od tematu... $N, masz relikwie, o które prosiłam?', 0),
(5944, 'plPL', '<Tirion odzyskuje panowanie nad sobą.>', 0),
(6004, 'plPL', 'Jak idzie, $N? Są silniejsi, niż $gmyślałeś:myślałaś;? Mam nadzieję, że nie. Jeśli mam tu doprowadzić sprawę do końca, trzeba będzie o wiele więcej siły niż to, o co już cię prosiłam.', 0),
(6023, 'plPL', '$GZnalazłeś:Znalazłaś; ich już, $N? Gdy ta dwójka zostanie załatwiona, będę mogła wejść do Żagiewia i przyjrzeć się z bliska ich rozmieszczeniu. Nie dam rady bez twojej pomocy. Proszę, znajdź dla mnie Radley i Durgena.', 0),
(6025, 'plPL', 'To niebezpieczne zadanie, $N. Zazdroszczę ci odwagi.', 0),
(6028, 'plPL', 'Witaj, $N. W imieniu Argentowego Brzasku oferuję ci bezpieczeństwo i schronienie, dopóki przebywasz w Obozie Zimnych Wichrów. Może też mam dla ciebie jakąś pracę...', 0),
(6389, 'plPL', '$GZrobiłeś:Zrobiłaś; to, $N? $GWypuściłeś:Wypuściłaś; termity? Niech Światłość nas wspiera, jeśli Szkarłatnej Krucjacie uda się utrzymać i tartak, i Żagiewie. Nie powinni mieć ani jednego, ani drugiego. Żerują tylko na ofiarach ostatniej wojny i powinno się ich wybić jak wściekłe zwierzęta!', 0),
(6569, 'plPL', 'Oczy tego, kogo chcemy naśladować, to najważniejszy składnik każdej iluzji, $N.$B$B<Myranda wskazuje worek niemal przepełniony gałkami ocznymi, z etykietą „Szkarłatna Krucjata”.>$B$B<Myranda się śmieje.>', 0),
(8414, 'plPL', 'Jakie zło mi $gprzyniosłeś:przyniosłaś;?', 0),
(8416, 'plPL', 'Czy Thal\'danisowi udało się oczyścić kamienie Plagi?', 0),
(8418, 'plPL', '$GZabiłeś:Zabiłaś; te nędzne trolle?', 0),
(9446, 'plPL', 'Czy nie $gmiałeś:miałaś; iść z anachoretą Truuenem do Grobowca Uthera?', 0),
(9474, 'plPL', 'Znak Światłodzierżcy to potężny symbol wiary Uthera w Światłość.', 0);
INSERT INTO `quest_greeting_locale` (`ID`, `type`, `locale`, `Greeting`, `VerifiedBuild`) VALUES
(10926, 0, 'plPL', 'Już nigdy nie jest mi ciepło...', 0);
