INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(292, 'plPL', 'Tu spoczywa Uther Światłodzierżca$BPierwszy paladyn – założyciel Zakonu Srebrnej Dłoni$B$BUther żył i zginął w obronie królestwa Lordaeronu. Choć zdradził go najukochańszy uczeń, wierzymy, że jego duch wciąż żyje. Nadal nad nami czuwa, nawet gdy cienie zacieśniają się wokół naszej zrujnowanej ziemi. Jego światło jest światłem całej ludzkości – i dopóki będziemy czcić jego przykład, nigdy nie zgaśnie. $B									– Anonim', 0),
(2351, 'plPL', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\14679_Tirion_256"/>\n</BODY>\n</HTML>\n', 0),
(2370, 'plPL', '<HTML>\n<BODY>\n<IMG src="Interface\\Pictures\\14679_Tirion_256"/>\n</BODY>\n</HTML>\n', 0),
(2371, 'plPL', 'Kroniki Włości Darrow\n\nWłości Darrow, nazwane tak od leżącego na zachód Jeziora Darrowmere, to wioska wtulona w południowe podnóża Lordaeronu. Znane z pokornych, lecz pracowitych mieszkańców, Włości Darrow pozostawały na uboczu historii Lordaeronu aż do Drugiej Wojny.\n\nW tamtej wojnie rodzili się bohaterowie. I bohaterowie ginęli.\n', 0),
(2372, 'plPL', 'Bitwa o Włości Darrow\n\nBitwa o Włości Darrow rozegrała się w środku Drugiej Wojny, gdy siły Plagi pustoszyły Lordaeron. Włości Darrow zostały odcięte od głównych sił Przymierza, ale miasteczko wzmocniła kompania wojska, oddział paladynów Srebrnej Dłoni i nieugięta grupa miejscowej milicji pod wodzą kapitana Josepha Redpatha.', 0),
(2373, 'plPL', 'Pierwsze ataki Plagi na Włości Darrow były nieliczne. Niewielkie grupy grasujących szkieletów i trupów krążyły po obrzeżach wioski i zostały odparte.\n\nAle Plaga nie ugięła się przed zawziętością obrońców i odpowiedziała tym samym; wkrótce po pierwszej fali ataków nadeszła druga. Czempioni ghuli, słudzy władcy ghuli Horgusa, z wrzaskiem runęli ze wzgórz i starli się z osaczonymi obrońcami Włości Darrow.', 0),
(2374, 'plPL', 'Obrońcy słabli, ale z odsieczą przybyli im paladyni, uczniowie Srebrnej Dłoni. Ich przywódca, Davil Crokford, pochodził z Włości Darrow. Gdy usłyszał o nadciągającym ataku, przyprowadził swoich towarzyszy do wioski i wspólnie z obrońcami powstrzymali sługi Horgusa.\n\nGdy do bitwy wkroczył sam Horgus, zmierzył się z Davilem. Walczyli przez wiele minut i w końcu Davil zwyciężył, lecz odniósł śmiertelną ranę i zmarł wkrótce po pokonaniu władcy ghuli.', 0),
(2375, 'plPL', 'Bitwa trwała dalej, a kapitan Redpath dzielnie dowodził swoją milicją. Być może udałoby się ją wygrać, gdyby kapitana nie spaczył rycerz śmierci Marduk Czarny.\n\nW samym środku zamętu Marduk podjechał do Redpatha i czarną magią wyrwał jego ducha, wypaczając go w złowrogi cień dzielnego kapitana.', 0),
(2376, 'plPL', 'Spaczony kapitan Redpath zaraził następnie swoim złem obrońców Włości Darrow, którzy zdradzili sojuszników i ich wyrżnęli. Potem zwrócili się przeciwko samym Włościom Darrow i wymordowali wszystkich, którzy ukrywali się w domach.\n\nPozostała armia Plagi wraz ze spaczonym duchem kapitana Redpatha opuściła spustoszoną wioskę i wdarła się w głąb Lordaeronu, pomnażając ból i śmierć Drugiej Wojny.', 0),
(2377, 'plPL', 'Kroniki Włości Darrow\n\nWłości Darrow, nazwane tak od leżącego na zachód Jeziora Darrowmere, to wioska wtulona w południowe podnóża Lordaeronu. Znane z pokornych, lecz pracowitych mieszkańców, Włości Darrow pozostawały na uboczu historii Lordaeronu aż do Drugiej Wojny.\n\nW tamtej wojnie rodzili się bohaterowie. I bohaterowie ginęli.', 0),
(2378, 'plPL', 'Bitwa o Włości Darrow\n\nBitwa o Włości Darrow rozegrała się w środku Drugiej Wojny, gdy siły Plagi pustoszyły Lordaeron. Włości Darrow zostały odcięte od głównych sił Przymierza, ale miasteczko wzmocniła kompania wojska, oddział paladynów Srebrnej Dłoni i nieugięta grupa miejscowej milicji pod wodzą kapitana Josepha Redpatha.', 0),
(2379, 'plPL', 'Pierwsze ataki Plagi na Włości Darrow były nieliczne. Niewielkie grupy grasujących szkieletów i trupów krążyły po obrzeżach wioski i łatwo je pokonano.\n\nAle Plaga wyczuła zawziętość obrońców i odpowiedziała tym samym; wkrótce po pierwszej fali ataków nadeszła druga. Czempioni ghuli, słudzy władcy ghuli Horgusa, z wrzaskiem runęli ze wzgórz i starli się z osaczonymi obrońcami Włości Darrow.', 0),
(2380, 'plPL', 'Obrońcy słabli, ale z odsieczą przybyli im paladyni, uczniowie Srebrnej Dłoni. Ich przywódca, Davil Crokford, pochodził z Włości Darrow. Gdy usłyszał o nadciągającym ataku, przyprowadził swoich towarzyszy do wioski i wspólnie z obrońcami powstrzymali sługi Horgusa.\n\nGdy do bitwy wkroczył sam Horgus, zmierzył się z Davilem. Walczyli przez wiele minut i w końcu Davil zwyciężył, lecz odniósł śmiertelną ranę i zmarł wkrótce po pokonaniu władcy ghuli.', 0),
(2381, 'plPL', 'Bitwa trwała dalej, a kapitan Redpath dzielnie dowodził swoją milicją. Być może udałoby się ją wygrać, gdyby kapitana nie spaczył rycerz śmierci Marduk Czarny.\n\nW samym środku zamętu Marduk podjechał do Redpatha i czarną magią wyrwał jego ducha, wypaczając go w złowrogi cień dzielnego kapitana.', 0),
(2382, 'plPL', 'Spaczony kapitan Redpath zaraził następnie swoim złem obrońców Włości Darrow, którzy zdradzili sojuszników i ich wyrżnęli. Potem zwrócili się przeciwko samym Włościom Darrow i wymordowali wszystkich, którzy ukrywali się w domach.\n\nPozostała armia Plagi wraz ze spaczonym duchem kapitana Redpatha opuściła spustoszoną wioskę i wdarła się w głąb Lordaeronu, pomnażając ból i śmierć Drugiej Wojny.', 0),
(2383, 'plPL', 'Los Horgusa Pustoszyciela\n\nHorgus Pustoszyciel poległ w bitwie o Włości Darrow. Ale zło, które w nim tkwiło, nie wygasło do końca. Zwycięskie siły Plagi zabrały jego czaszkę z pola bitwy i niosły ją ze sobą, by siać strach wśród żywych, z którymi się mierzyły.\n\nKilka dni później oddział Plagi, który miał głowę, został pokonany przez paladynów Srebrnej Dłoni. Głowę Horgusa wrzucono do Jeziora Czarnego Lasu.', 0),
(2384, 'plPL', 'Los Marduka Czarnego\n\nMarduk przeżył Drugą Wojnę, siejąc śmierć i cierpienie swoim plugawym, pokrytym runami mieczem. Choć Marduk wciąż żyje, jego miecz przepadł w bitwie w pobliżu Przeprawy Corina. Krasnoludzki kapitan roztrzaskał miecz o swoją zaczarowaną tarczę, zmuszając Marduka do ucieczki z pola bitwy i zapewniając Przymierzu zwycięstwo.\n\nMiecz Marduka zapadł się w ziemię i ją skaził, wyżerając w niej wąwóz, znany dziś jako Blizna Infectis.', 0),
(2385, 'plPL', 'Los Davila Kuźni Światła\n\nDavil Kuźnia Światła zginął w bitwie o Włości Darrow, ale jego odwaga natchnęła Przymierze na całą wojnę.\n\nJego księgę, paladyński libram, odzyskały oddziały Szkarłatnej Krucjaty. Znajduje się teraz w ratuszu Żagiewia, kontrolowanego przez Szkarłatną Krucjatę, i często czytają go krzyżowcy pragnący zaczerpnąć z siły Davila.', 0),
(2386, 'plPL', 'Los Josepha Redpatha\n\nJoseph Redpath zginął w bitwie o Włości Darrow. Jego duch został spaczony i przybrał nową postać, a ten stwór siał wielkie zło w Lordaeronie.\n\nNa Plonach Gahrrona, na wschód od Andorhalu, spaczony Redpath został w końcu pokonany przez siły Przymierza. Jego tarcza wciąż leży przy stodole zarażonego gospodarstwa, a słudzy Plagi wciąż ciągną do pamięci o jego złu.', 0),
(2391, 'plPL', 'Los Carlina Redpatha\n\nCarlin, brat kapitana Josepha Redpatha, padł w bitwie o Włości Darrow. Choć był ciężko ranny, nie zginął.\n\nKilka dni po bitwie agenci Argentowego Brzasku znaleźli Carlina błąkającego się w pobliżu Przeprawy Corina, osłabionego pragnieniem i gorączką. Opatrzyli jego rany i zabrali go do Kaplicy Świetlistej Nadziei.\n\nWdzięczny za ich miłosierdzie, Carlin wstąpił w szeregi Argentowego Brzasku i teraz toczy z Plagą bój o zemstę.', 0),
(2986, 'plPL', 'Gdy Nahni podpłynęła bliżej, zaprawiony w bojach wojownik zmierzył ją twardym spojrzeniem. „Pewnie przyszłaś odebrać nagrodę za zabicie tych murloków?”$B$BJej wzrok powędrował w dół, ku jarzącemu się pałaszowi u jego boku. „To zależy, co to za nagroda, Marcusie”. Figlarnie nawinęła kosmyk włosów na palec, udając, że nie widzi, jak niezręcznie się przy niej wierci. „Może wcale jej nie chcę”.', 0),
(2987, 'plPL', 'Marcus zrobił krok w jej stronę, najeżony mieszaniną strachu i gniewu. „Nagroda nie podlega negocjacjom!” Zatrzymał się na chwilę, zbierając się na odwagę, i przywarł do jej drobnej postaci. Ich usta zetknęły się gorąco, topiąc jej zaklęcie mroźnego pancerza w potoku parującej mgiełki.$B$B„No to co, czy to zadanie ma jeszcze jakiś etap?” – droczyła się, a jej oczy lśniły z podniecenia.$B$B<I tak dalej przez kilkaset stron, bez żadnego posuwania akcji do przodu.>', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(5788, 'plPL', '%s wydaje przeraźliwy skrzek.', '', 0),
(6018, 'plPL', '', 'Witaj, $N. Nazywają mnie Chronormu, ale możesz mówić do mnie Chromie. Taka poufałość mi nie przeszkadza.$B$BA teraz – pytasz, skąd znam twoje imię? Należę do Brązowego Stada, na zawsze zestrojonego z przypływami i odpływami czasu. Można powiedzieć, że już się spotkaliśmy. I tak samo jeszcze się spotkamy.', 0),
(6019, 'plPL', '', 'Witaj ponownie, $N. Wyczuwam, że biegowi czasu wciąż zagrażają siły naprawdę potężne. Brązowe Stado zawsze chętnie przyjmie twoją dalszą pomoc.$B$BPrzeszłość jest już ustalona, lecz przyszłość wciąż się zmienia. Decyzje, które podejmujesz tu i teraz, pomagają tę zmianę ukierunkować.', 0),
(6033, 'plPL', '%s zostaje przywołany przez szczelinę czasową!', '', 0),
(6159, 'plPL', 'Tytuł tej księgi wypisano ozdobnym pismem odręcznym: Dziennik Maureen Dalson.', '', 0),
(6160, 'plPL', 'Dziennik o pożółkłych kartkach leży otwarty na ostatnim wpisie:$B$B„Nie wiem, co teraz będzie, skoro Harold się przemienił. Resztką sił zawlokłam go do jedynego miejsca, jakie znalazłam, gdzie dało się go szczelnie zamknąć i zatrzymać. Klucz ukryłam przy sobie i modlę się, żeby to wystarczyło...$B$BMam nadzieję, że zdołam się stąd wydostać, ale potrzebuję na to pieniędzy. Chyba wszystkie nasze rzeczy są w szafce... a teraz, jak o tym myślę, czy to nie Harold nosi przy sobie klucz?$B$BPrześpię się z tym, jestem śmiertelnie zmęczona”.', '', 0),
(6274, 'plPL', 'Ratuj mnie...', '', 0),
(6345, 'plPL', 'Księga opowiada o smokach, które zjednoczyły się przeciwko innemu, potężniejszemu smokowi imieniem Śmiercioskrzydły. Z tego, co udaje ci się odczytać, Chromatyczne Stado omal nie zostało wypuszczone na świat. Aspekty były przygotowane.\n', '', 0),
(6416, 'plPL', '', 'Hurra! Moja lalka!', 0),
(6417, 'plPL', '', 'Nie dopuścisz do mnie złych ludzi, prawda?', 0),
(6418, 'plPL', '', 'Poznajmy całą historię. Do tego potrzeba odrobiny magii...', 0),
(6419, 'plPL', '', 'Już, gotowe. Księga została wzbogacona...', 0),
(6555, 'plPL', 'Fortuna jest moja, Alexi! Wkrótce nadejdzie twój koniec!', '', 0),
(6641, 'plPL', '', 'Skoro kotły zostały przełamane, możemy teraz wprowadzać przeciwśrodek do otoczenia. Plaga posmakuje, że tak powiem, własnego lekarstwa!$B$BO odczynniki potrzebne do kotłów pytaj alchemika Arbingtona. Ja zajmę się wszystkimi raportami o tym, jak ogólnie nam idzie obracanie zarazy przeciw Pladze!', 0),
(6644, 'plPL', '', 'Witaj, $gmłody panie:młoda panienko;. Jestem Eva Sarkhoff, a to mój mąż, Lucien. Miło nam cię poznać.', 0),
(6645, 'plPL', 'Cała przyjemność po mojej stronie, pani. Czy mogę zapytać, co tu robicie?', 'Cała przyjemność po mojej stronie, pani. Czy mogę zapytać, co tu robicie?', 0),
(6646, 'plPL', '', 'Oczywiście, $gpanie:panienko;. Byliśmy niegdyś służbą rodu Barovów – w miejscu, które dziś znane jest jako Scholomancjum.$B$BJa byłam przełożoną pokojówek, a Lucien kamerdynerem pana Barova.$B$BPracowaliśmy dla Barovów przez dziesięciolecia, aż...$B$B<Eva płacze.>', 0),
(6647, 'plPL', 'Aż do czego, Evo? Muszę wiedzieć.', 'Aż do czego, Evo? Muszę wiedzieć.', 0),
(6648, 'plPL', '', 'Och, to takie okropne, $gpanie:panienko;. Dom Barovów był niegdyś pełen życia... pełen przepychu. Dwór był główną siedzibą Barovów pośród ich rozległego imperium.$B$BZ biegiem dni Lucien i ja zauważyliśmy, że Barovowie popadają w przygnębienie. W rozpacz. Pana i panią często ogarniały paranoja i wściekłość. Nocami słyszeliśmy, jak Barovowie kłócą się w swoich komnatach. Z tego, co rozumieliśmy, ich chciwość, że tak powiem, „przerwała tamę”.', 0),
(6650, 'plPL', '', 'Podejrzewamy, że aby zachować fortunę i władzę nad ziemią – długo po kresie swojego życia – Barovowie zawarli układ z potężnym ludzkim magiem imieniem Kel\'Thuzad.$B$B<Eva wzdryga się.>$B$BZ tego układu zrodziła się szkoła nekromancji: miejsce, które wydało Kult Potępionych i miało stać się jego stolicą.$B$BZ każdym tygodniem dom Barovów coraz bardziej niszczał...$B$BMroczne istoty zaczęły zamieszkiwać różne skrzydła domu. Utrzymanie go stało się niemożliwe... i obrzydliwe.', 0),
(6651, 'plPL', 'Czemu po prostu nie odeszliście?', 'Czemu po prostu nie odeszliście?', 0),
(6652, 'plPL', '', 'I dokąd mielibyśmy pójść? To było wszystko, co znaliśmy; wszystko, co kiedykolwiek znaliśmy i mieliśmy poznać.$B$BW końcu straciliśmy kontakt z Barovami, a w końcu odcięto nas od reszty domowników. Nie wiedzieliśmy, co stało się z resztą służby – wiedzieliśmy tylko, że były krzyki. Krzyki torturowanych.$B$BWiedząc, że nie mamy dokąd pójść, Lucien i ja musieliśmy ukrywać się w naszych kwaterach. W dzień, gdy w szkole było względnie cicho, Lucien wymykał się, by zdobyć coś do jedzenia i picia.', 0),
(6654, 'plPL', '', 'Robiliśmy tak przez mniej więcej pół roku i patrzyliśmy, jak dom przechodzi przerażające zmiany. Plugawe potwory swobodnie krążyły po dworze. Mroczni kultyści zapełnili każdy skrawek przeróżnymi przedmiotami do rytuałów i ofiar. Wiedzieliśmy, że długo już się nie ukryjemy.$B$BJak można było się spodziewać, znaleziono nas i pojmano. Zdarli z nas całe ubranie i położyli nas w kręgu z krwi. Siedzieliśmy tam całymi dniami, nadzy i przerażeni.', 0),
(6655, 'plPL', 'Bez więzów? Po prostu w kręgu?', 'Bez więzów? Po prostu w kręgu?', 0),
(6656, 'plPL', '', 'Więzów? Na tym świecie są rzeczy, które krępują o wiele skuteczniej niż kraty i kajdany, $gmłody panie:młoda panienko;. Otaczali nas nieumarli i bez przerwy dręczyli nas przerażającymi, zwyrodniałymi czynami.$B$BW końcu przyszedł on. Przedstawił się jako doktor Theolen Krastinov. My poznaliśmy go jako „Rzeźnika”.\n', 0),
(6657, 'plPL', 'Opowiedz mi więcej.', 'Opowiedz mi więcej.', 0),
(6658, 'plPL', '', 'W końcu zrozumieliśmy, skąd brały się te krzyki. Rzeźnik zadawał nam ból, o którego istnieniu nie mieliśmy pojęcia. Używał nas w niezliczonych eksperymentach, próbując stworzyć zarazę.$B$BDni zamieniały się w tygodnie. Zmarlibyśmy już pierwszego dnia, gdyby ten okrutny potwór nie utrzymywał nas przy życiu za pomocą magii.', 0),
(6659, 'plPL', 'To okropne zbrodnie.', 'To okropne zbrodnie.', 0),
(6660, 'plPL', '', 'Rzeźnik mówił o „krwi niewinnych” i o swoim mrocznym panu, „Kirtonosie”. O tym, że musi ułagodzić swojego pana.$B$BW końcu bestia skończyła swoje eksperymenty. Wyssano z nas całe życie. Nasze duchy były strzaskane. Słodkie objęcia śmierci były tuż-tuż i witaliśmy je z otwartymi ramionami. Ale w swoim bezgranicznym okrucieństwie Rzeźnik wyciągnął nas z progu śmierci.$B$BMieliśmy zostać przy życiu i zostać rzuceni na pożarcie jego wygłodniałym ghulom. Śmiał się, patrząc, jak te potwory pożerają nasze ciała.', 0),
(6661, 'plPL', 'Robi mi się niedobrze.', 'Robi mi się niedobrze.', 0),
(6662, 'plPL', '', 'My nie czujemy nic. Nasze dusze pozostają tutaj, w zawieszeniu. Nie możemy odejść, dopóki nasze szczątki nie zostaną odnalezione, a duchy ukojone.', 0),
(6799, 'plPL', 'Evo, $gzgubiłem:zgubiłam; widmową esencję. Potrzebuję nowej.', 'Evo, $gzgubiłem:zgubiłam; widmową esencję. Potrzebuję nowej.', 0),
(6806, 'plPL', '', 'Do biegu. Gotowe. START!', 0),
(6807, 'plPL', '', 'EJ! Tak nie wolno!', 0),
(6808, 'plPL', '', 'Wygrałam!!', 0),
(6809, 'plPL', '', 'Jeszcze raz? Do dwóch wygranych!', 0),
(6810, 'plPL', '', 'Oszukiwałaś!', 0),
(6817, 'plPL', 'Nie widzisz, że przygotowujemy się do wizyty Uthera? Zejdź mi z drogi, mam mnóstwo pracy!', 'Nie widzisz, że przygotowujemy się do wizyty Uthera? Zejdź mi z drogi, mam mnóstwo pracy!', 0),
(6818, 'plPL', '$GPróbowałeś:Próbowałaś; już naszego chleba? Piekarz Masterson to chyba najzdolniejszy kucharz, jaki kiedykolwiek żył!', '$GPróbowałeś:Próbowałaś; już naszego chleba? Piekarz Masterson to chyba najzdolniejszy kucharz, jaki kiedykolwiek żył!', 0),
(6819, 'plPL', 'Witaj w Caer Darrow, $gnieznajomy:nieznajoma;.', 'Witaj w Caer Darrow, $gnieznajomy:nieznajoma;.', 0),
(6820, 'plPL', 'Nie jesteśmy naprawdę niegrzeczni, $gnieznajomy:nieznajoma;, po prostu wszyscy się śpieszą, żeby wszystko było idealne na przybycie Uthera. Nieczęsto Światłodzierżca odwiedza nasze miasto.', 'Nie jesteśmy naprawdę niegrzeczni, $gnieznajomy:nieznajoma;, po prostu wszyscy się śpieszą, żeby wszystko było idealne na przybycie Uthera. Nieczęsto Światłodzierżca odwiedza nasze miasto.', 0),
(6821, 'plPL', 'Kolejny piękny dzień na naszej pięknej wyspie.', 'Kolejny piękny dzień na naszej pięknej wyspie.', 0),
(6822, 'plPL', 'Uważaj, $gnieznajomy:nieznajoma;. Nie tolerujemy w naszym mieście łotrów.', 'Uważaj, $gnieznajomy:nieznajoma;. Nie tolerujemy w naszym mieście łotrów.', 0),
(6823, 'plPL', 'Mam cię na oku.', 'Mam cię na oku.', 0),
(6824, 'plPL', 'Mam w sobie mnóstwo tłumionego gniewu i wrogości. Daj mi tylko powód, obdartusie.', 'Mam w sobie mnóstwo tłumionego gniewu i wrogości. Daj mi tylko powód, obdartusie.', 0),
(6825, 'plPL', 'Ho, ho, wyglądasz jak zwykły uliczny łobuz!', 'Ho, ho, wyglądasz jak zwykły uliczny łobuz!', 0),
(6826, 'plPL', 'W Caer Darrow nie wolno się włóczyć, żebrać, przeklinać, bić się ani robić niczego innego, co ci chodzi po głowie.', 'W Caer Darrow nie wolno się włóczyć, żebrać, przeklinać, bić się ani robić niczego innego, co ci chodzi po głowie.', 0),
(6859, 'plPL', 'Niektórych oszczędzono od udręki, jaką niosą wspomnienia.', '', 0),
(6863, 'plPL', 'Dom Barovów naprawdę nie daje mi odpocząć. Ciągle wychodzą stamtąd jakieś odpadki.', '', 0),
(6864, 'plPL', 'Moje stanowisko to specjalista do spraw wywozu nieczystości.', '', 0),
(6865, 'plPL', 'Może $gpowinieneś:powinnaś; mówić do tych urządzeń wzmacniających dźwięk, przymocowanych do moich PIĘŚCI FURII.', '', 0),
(6866, 'plPL', 'Ach, moja słodka Brandy, jak ja za nią tęsknię!', '', 0),
(6870, 'plPL', '', 'Bądź $gpozdrowiony:pozdrowiona;, $gprzyjacielu:przyjaciółko;. Jestem oficer Czyste Serce i z dumą należę do ogólnoświatowej organizacji zwanej Krucjatą Argentu. Nasza sprawa jest prosta – walczyć szybko i bezlitośnie z każdym przejawem zła, który pojawi się w Azeroth. Nie jesteśmy ciałem politycznym i nigdy nie chcemy się nim stać. Dlatego zarówno Przymierze, jak i Hordę nazywamy przyjaciółmi – przyjaciółmi w sprawie wykorzenienia zła!$B$BZa Światłość, $gbracie:siostro;!', 0),
(6879, 'plPL', 'Krucjata Argentu pozdrawia cię, $N! Nazywam się Iskra Światłości i jestem upoważnionym kwatermistrzem Krucjaty od wyposażenia i sprzętu.$B$BGdy będziesz walczyć ze złem pod naszym Zleceniem – zdobywając przy tym nasz szacunek i zaufanie – będziesz otrzymywać od oficer Czyste Serce żetony męstwa. Żetony służą dwóm celom: możesz nimi podnieść swoją pozycję w naszych szeregach albo płacić nimi za specjalne przedmioty.$B$BW miarę jak twoja pozycja w Krucjacie będzie rosnąć, odkryjesz, że udostępniamy ci coraz więcej przedmiotów.', '', 0),
(6889, 'plPL', 'Rasa nie decyduje o honorze. Dopóki przebywasz w moim gospodarstwie, proszę, byś $gpamiętał:pamiętała; o tej zasadzie i ją szanował.$B$BZnałem orków, którzy byli tak honorowi jak najszlachetniejsi rycerze, i ludzi, którzy byli tak podli jak najbezwzględniejsze sługi Plagi.$B$BAle nie będę cię zanudzał opowieściami z mojej młodości! Jest mnóstwo pracy do wykonania – jeśli tego pragniesz.', '', 0),
(7126, 'plPL', '', 'Witaj, $N. Nie mam za wiele czasu na rozmowy – Zimnych Wichrów używam tylko jako obozu, żeby odpocząć przed wyprawą do Żagiewia. Doszły mnie słuchy, że zanim oszaleli, Szkarłatna Krucjata miała na usługach maga, który próbował tworzyć dla jej żołnierzy potężne łuki i strzelby. Nie wiem na pewno, czy mu się udało... Krucjata zabiła go, zanim którykolwiek z jego wyrobów wyszedł poza mury. Może zabili go, żeby zachować to w tajemnicy... a może aż tak nie ufają magii.', 0),
(7127, 'plPL', '', 'Wi... witaj, $N. Przepraszam, dochodzę do siebie po ranach.$B$BCi szkarłatni krzyżowcy są twardsi, niż sądziłam. Omal mnie nie wykończyli.$B$BTy też $gpowinieneś:powinnaś; uważać. Nie chciałabym, żeby cię zaskoczyli.', 0),
(7129, 'plPL', 'Dawno temu, przed ostatnią wielką wojną, mój ojciec prowadził Tartak Północnego Grzbietu. To było całe jego życie i był mu oddany. Potem przyszła wojna i choć sprawiało mu to ból, musieliśmy uciekać do Wichrogrodu.$B$BW tamtych dniach straciliśmy wielu przyjaciół i krewnych, a boli mnie świadomość, że Szkarłatna Krucjata zajęła tartak do własnych celów.$B$BDlatego wróciłem.', '', 0),
(7219, 'plPL', 'Jestem $ggotów:gotowa; wysłuchać twojej opowieści, Tirionie.', 'Jestem $ggotów:gotowa; wysłuchać twojej opowieści, Tirionie.', 0),
(7220, 'plPL', 'Muszę cię przeprosić, że nie byłem z tobą do końca szczery co do tego, kim jestem. Musiałem mieć pewność, że można ci zaufać – niewielu bezinteresownie pomogłoby staremu, zapomnianemu pustelnikowi.$B$B$GDowiodłeś:Dowiodłaś;, że jesteś jedną z tych osób: osobą prawą i honorową.', '', 0),
(7221, 'plPL', 'Dziękuję, Tirionie. Kim więc jesteś?', 'Dziękuję, Tirionie. Kim więc jesteś?', 0),
(7222, 'plPL', 'Mój syn Taelan był jeszcze dzieckiem, gdy uznano mnie winnym zdrady i wygnano z Przymierza, skazując na życie na wygnaniu. Postanowiłem zostać tutaj, by móc nad nim czuwać – by jakoś zapewnić, że wyrośnie na honorowego człowieka.$B$BTak jak miałem nadzieję, zajął moje miejsce jako lord Mardenholde; ale okrutnym zrządzeniem losu wstąpił w szeregi Szkarłatnej Krucjaty. Jest teraz jej najwyższym lordem.', '', 0),
(7223, 'plPL', 'To straszne.', 'To straszne.', 0),
(7224, 'plPL', 'W istocie. Szkarłatna Krucjata to wynaturzenie Zakonu Srebrnej Dłoni.$B$BMusisz mi uwierzyć: Taelan jest dobrym człowiekiem. Potrzebuje przewodnictwa. Musi sobie przypomnieć... przypomnieć, co to znaczy być szlachetnym i honorowym. Wiem, że w głębi serca wie, że to, co robi, jest złe. Pomożesz mu? Pomożesz mu sobie przypomnieć?', '', 0),
(7225, 'plPL', 'Pomogę, Tirionie.', 'Pomogę, Tirionie.', 0),
(7313, 'plPL', 'Poprowadzę nas przez Żagiewie na skraj lasu. Stamtąd zabierzesz mnie do mojego ojca.', '', 0),
(7314, 'plPL', 'Zdejmij przebranie, bo inaczej, gdy owładnie mną furia, poczujesz ukąszenie mojego ostrza.', '', 0),
(7315, 'plPL', 'Stać.', '', 0),
(7316, 'plPL', '%s przywołuje swojego wierzchowca.', '', 0),
(7329, 'plPL', 'To już niedaleko. Główna droga jest tuż przed nami.', '', 0),
(7370, 'plPL', 'Isillien!', '', 0),
(7371, 'plPL', 'To nie twoja walka, $gnieznajomy:nieznajoma;. Broń się przed atakami Karmazynowej Elity. Ja zmierzę się z wielkim inkwizytorem.', '', 0),
(7372, 'plPL', 'Coś ty uczynił, Isillienie? Niegdyś walczyłeś z honorem, dla dobra naszego ludu... a teraz... zamordowałeś mojego chłopca...', '', 0),
(7373, 'plPL', 'Niech twoja dusza płonie w męczarniach, Isillienie! Światłości, daj mi siłę do walki z tym potworem.', '', 0),
(7374, 'plPL', 'Stań do walki, tchórzu. Zmierz się z wiarą i siłą, którą niegdyś uosabiałeś.', '', 0),
(7397, 'plPL', 'Pamela? Jesteś tam, kochanie?', '', 0),
(7399, 'plPL', '', 'Tatuś!', 0),
(7400, 'plPL', '', 'Tatuś! Wróciłeś!', 0),
(7401, 'plPL', '', 'Chodźmy się bawić! Nie, opowiedz mi bajkę, tatusiu! Nie... chodźmy zbierać kwiatki! I bawić się w podwieczorek! Znalazłam moją laleczkę, mówiłam ci?', 0),
(7402, 'plPL', '', 'Tak bardzo za tobą tęskniłam, tatusiu!', 0),
(7403, 'plPL', 'Ja też za tobą tęskniłem, kochanie. I wreszcie jestem w domu...', '', 0),
(7408, 'plPL', 'Wszyscy byliśmy świadkami strasznych tragedii, ale nie możemy pozwolić, by pogrążyły nas w rozpaczy.$B$BZamiast tego zachowaj te wspomnienia blisko serca, byśmy pewnego dnia mogli wyrównać rachunki.', '', 0),
(7420, 'plPL', 'Istnieje tysiąc takich jak on. Dziesięć tysięcy. Gdy jeden upadnie, powstanie kolejny, by zasiąść na tronie władzy.', '', 0),
(7421, 'plPL', '%s pada na jedno kolano.', '', 0),
(7423, 'plPL', 'Spójrzcie, co zrobili mojemu chłopcu.', '', 0),
(7426, 'plPL', 'Twoja śmierć nie pójdzie na marne, Taelanie. Tego dnia rodzi się nowy Zakon... Zakon, który poświęci się wytępieniu zła nękającego ten świat. Zła, które nie może się ukryć za polityką i uprzejmościami.', '', 0),
(7429, 'plPL', 'Zbyt długo siedziałem bezczynnie, spowity tą mgłą... tą niemocą, opłakując to, co mogło się stać... co powinno się stać.', '', 0),
(7430, 'plPL', 'To obiecuję... To przysięgam...', '', 0),
(7455, 'plPL', 'Ciemność zasnuła mi oczy, ale ty $gwyrwałeś:wyrwałaś; mnie z tego bezbożnego odrętwienia. $GOcaliłeś:Ocaliłaś; mnie, $N.$B$BA teraz błagam cię... wybacz mi.', '', 0),
(7646, 'plPL', 'Opowiedz mi więcej.', 'Opowiedz mi więcej.', 0),
(8222, 'plPL', 'Solidna skrzynia stoi pośrodku tartaku, otoczona gruzem i bardzo gorliwymi wyznawcami Szkarłatnej Krucjaty.', '', 0),
(8223, 'plPL', 'Postaw beczkę z termitami na skrzyni.', 'Postaw beczkę z termitami na skrzyni.', 0),
(9015, 'plPL', '', 'O co prosisz Błękitne Stado?', 0),
(9016, 'plPL', 'Haleh, $gzgubiłem:zgubiłam; amulet smoczego ognia. Czy możesz wykonać nowy?', 'Haleh, $gzgubiłem:zgubiłam; amulet smoczego ognia. Czy możesz wykonać nowy?', 0),
(9764, 'plPL', '%s wpada w morderczy szał!', '', 0),
(11319, 'plPL', '', '%s pada na jedno kolano.', 0),
(11503, 'plPL', 'Gdzie jest Nestor Wiatrobieg?', 'Gdzie jest Nestor Wiatrobieg?', 0),
(11504, 'plPL', 'Nestor Wiatrobieg mieszka w Wieży Koronnej Straży na Wschodnich Plagowiskach.', 'Nestor Wiatrobieg mieszka w Wieży Koronnej Straży na Wschodnich Plagowiskach.', 0),
(13611, 'plPL', 'Na Światłość, opuścisz ten grobowiec!', '', 0),
(13612, 'plPL', 'Witaj. Co cię dziś sprowadza do Obozu Zimnych Wichrów?', '', 0),
(13613, 'plPL', 'Zaczynamy, $gprzyjacielu:przyjaciółko;?', '', 0),
(13614, 'plPL', 'W tej okolicy roi się od plugawych sług Plagi. Może warto poświęcić chwilę na przygotowanie wszelkich środków obrony, jakie masz pod ręką.', '', 0),
(13615, 'plPL', 'Dobrze, ruszajmy dalej.', '', 0),
(13616, 'plPL', 'Uwaga! Atakują nas!', '', 0),
(13617, 'plPL', 'To pewnie czystość Znaku Światłodzierżcy przyciąga do nas Plagę. Musimy iść ostrożnie, żeby nas nie przytłoczyli!', '', 0),
(13618, 'plPL', 'Znów nas napadli! Broń się!', '', 0),
(13619, 'plPL', 'Tę ziemię naprawdę trzeba oczyścić Światłością! Chodźmy dalej, do grobowca. To już niedaleko.', '', 0),
(13621, 'plPL', 'Witajcie, przyjaciele!', '', 0),
(13624, 'plPL', 'Dziękuję ci, $gprzyjacielu:przyjaciółko;, że to $gumożliwiłeś:umożliwiłaś;. Tego dnia nigdy nie zapomnę! Chyba zostanę tu na chwilę. Proszę, wróć do arcykapłanki MacDonnell w obozie. Wiem, że bardzo ją zainteresuje, co się tu wydarzyło.', '', 0),
(14040, 'plPL', 'Jak idą poszukiwania Znaku?', '', 0),
(24143, 'plPL', '%s wpada w morderczy szał!', '', 0),
(29007, 'plPL', '', 'Tatuś!', 0),
(66412, 'plPL', 'Czas na małą operację na otwartym sercu!', '', 0),
(66413, 'plPL', 'Przekazuję... swoje ciało... nauce...', '', 0),
(66414, 'plPL', 'Kolejna udana operacja!', '', 0);
